	NodeDocument
)

// Node is a minimal DOM node.
type Node struct {
	Type     NodeType
	Tag      string
	Attrs    map[string]string
	AttrList []Attr
	Children []*Node
	Parent   *Node
	Text     string
	// SelfClosing marks a start tag that was written as "<tag/>"
	SelfClosing bool
