// Attr is a single attribute.
type Attr struct {
	Name  string
	Value string
}

// Get returns the value of an attribute.
func (n *Node) Get(name string) string {
	if n == nil {
		return ""
	}
	return n.Attrs[name]
}

// Classes returns the space separated class list.
func (n *Node) Classes() []string {
	v := n.Get("class")
	if v == "" {
