	if t.pos >= len(t.src) {
		t.done = true
		return token{}, false
	}
	if t.raw != "" {
		tok := t.rawText()
		return tok, true
	}
	if t.src[t.pos] != '<' {
		// text
		start := t.pos
		for t.pos < len(t.src) && t.src[t.pos] != '<' {
			t.pos++
		}
		return token{kind: tkText, text: decodeEntities(t.src[start:t.pos], t.rcdata)}, true
	}
	// '<'
	if strings.HasPrefix(t.src[t.pos:], "<!--") {
		start := t.pos + 4
		idx := strings.Index(t.src[start:], "-->")
		end := len(t.src)
		if idx >= 0 {
			end = start + idx
		}
		tok := token{kind: tkComment, data: t.src[start:end]}
		if idx >= 0 {
			t.pos = end + 3
		} else {
			t.pos = len(t.src)
		}
		return tok, true
	}
	if strings.HasPrefix(t.src[t.pos:], "<![CDATA[") {
		start := t.pos + 9
		idx := strings.Index(t.src[start:], "]]>")
		end := len(t.src)
		if idx >= 0 {
			end = start + idx
		}
		tok := token{kind: tkText, text: t.src[start:end]}
		if idx >= 0 {
			t.pos = end + 3
		} else {
			t.pos = len(t.src)
		}
		return tok, true
	}
	if strings.HasPrefix(t.src[t.pos:], "<!") || strings.HasPrefix(t.src[t.pos:], "<?") {
		start := t.pos + 2
		idx := strings.IndexByte(t.src[start:], '>')
		end := len(t.src)
		if idx >= 0 {
			end = start + idx
		}
		tok := token{kind: tkDoctype, data: t.src[start:end]}
		if idx >= 0 {
			t.pos = end + 1
		} else {
			t.pos = len(t.src)
		}
		return tok, true
	}
	rest := t.src[t.pos:]
	if len(rest) >= 2 && rest[1] == '/' {
		// end tag
		i := 2
		for i < len(rest) && !isTagSpace(rest[i]) && rest[i] != '>' {
			i++
		}
		name := strings.ToLower(rest[2:i])
		// skip attrs
		j := i
		depth := 0
		for j < len(rest) && rest[j] != '>' {
			if rest[j] == '"' || rest[j] == '\'' {
				q := rest[j]
				j++
				for j < len(rest) && rest[j] != q {
					j++
				}
				if j < len(rest) {
					j++
				}
				continue
			}
			j++
		}
