func (t *tokenizer) startTag() token {
	rest := t.src[t.pos:]
	i := 1
	for i < len(rest) && !isTagSpace(rest[i]) && rest[i] != '>' {
		i++
	}
	name := strings.ToLower(rest[1:i])
	tok := token{kind: tkStart, data: name, attrs: map[string]string{}}
	j := i
	selfClosing := false
	for j < len(rest) {
		// skip whitespace
		for j < len(rest) && isTagSpaceExceptSlash(rest[j]) {
			j++
		}
		if j >= len(rest) {
			break
		}
		if rest[j] == '>' {
			j++
			break
		}
		if rest[j] == '/' {
			// possible self-closing
			if j+1 < len(rest) && rest[j+1] == '>' {
				selfClosing = true
				j += 2
				break
			}
			j++
			continue
		}
		// attribute name
		k := j
		for k < len(rest) && !isTagSpaceExceptSlash(rest[k]) && rest[k] != '=' && rest[k] != '>' {
			k++
		}
		if k == j {
			j++
			continue
		}
		aname := strings.ToLower(rest[j:k])
		j = k
		// skip whitespace
		for j < len(rest) && isTagSpaceExceptSlash(rest[j]) {
			j++
		}
		var value string
		if j < len(rest) && rest[j] == '=' {
			j++
			for j < len(rest) && isTagSpaceExceptSlash(rest[j]) {
				j++
			}
			if j < len(rest) && (rest[j] == '"' || rest[j] == '\'') {
				q := rest[j]
				j++
				start := j
				for j < len(rest) && rest[j] != q {
					j++
				}
				value = rest[start:j]
				if j < len(rest) {
					j++
				}
			} else {
				start := j
				for j < len(rest) && !isTagSpaceExceptSlash(rest[j]) && rest[j] != '>' {
					j++
				}
				value = rest[start:j]
			}
		}
		aname = strings.ToLower(aname)
		if _, ok := tok.attrs[aname]; !ok {
			tok.attrList = append(tok.attrList, Attr{Name: aname, Value: value})
		}
		tok.attrs[aname] = value
	}
