	switch name {
	case "script", "style", "xmp", "iframe", "noembed", "noframes", "plaintext", "listing":
		t.raw = name
		t.rcdata = false
	case "textarea", "title", "noscript":
		t.raw = name
		t.rcdata = true
	}
