func (t *tokenizer) rawText() token {
	name := t.raw
	closing := "</" + name
	// find the closing tag (case-insensitive)
	idx := indexCaseInsensitive(t.src[t.pos:], closing)
	var data string
	if idx < 0 {
		data = t.src[t.pos:]
		t.pos = len(t.src)
	} else {
		data = t.src[t.pos : t.pos+idx]
		t.pos += idx
	}
	t.raw = ""
	if t.rcdata {
		data = decodeEntities(data, true)
	}
	return token{kind: tkText, text: data, attrs: map[string]string{}, data: name}
}

func indexCaseInsensitive(s, sub string) int {
	return strings.Index(strings.ToLower(s), strings.ToLower(sub))
}

// ---------------------------------------------------------------------------
// Entities
// ---------------------------------------------------------------------------

var entities = map[string]string{}

func decodeEntities(s string, _ bool) string {
	if !strings.Contains(s, "&") {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); {
		if s[i] != '&' {
			r, size := utf8.DecodeRuneInString(s[i:])
			b.WriteRune(r)
			i += size
			continue
		}
		// entity
		matched := false
		// try named entity (longest match) followed by optional ';'
		rest := s[i+1:]
		maxLen := 0
		maxName := ""
		for l := 1; l <= len(rest); l++ {
			sub := rest[:l]
			if v, ok := entities[sub]; ok {
				if l > maxLen {
					maxLen = l
					maxName = sub
					_ = v
				}
				continue
			}
			// stop when we see a character that can't be part of an entity name
			c := rest[l-1]
			if !isEntityNameChar(c) {
				break
			}
		}
		if maxName != "" {
			// decode
			b.WriteString(entities[maxName])
			i += 1 + maxLen
			if i < len(s) && s[i] == ';' {
				i++
			}
			matched = true
		}
		if matched {
			continue
		}
		// numeric
		if strings.HasPrefix(rest, "#") {
			j := 1
			radix := 10
			if j < len(rest) && (rest[j] == 'x' || rest[j] == 'X') {
				radix = 16
				j++
			}
			start := j
			for j < len(rest) && isDigit(rest[j], radix) {
				j++
			}
			if j > start {
				num := parseRadix(rest[start:j], radix)
				r := rune(num)
				switch {
				case r == 0, r > 0x10FFFF:
					r = 0xFFFD
				}
				b.WriteRune(r)
				i += 1 + j
				if i < len(s) && s[i] == ';' {
					i++
				}
				continue
			}
		}
		// not an entity: emit the '&' and continue
		b.WriteByte('&')
		i++
	}
	return b.String()
}

func isEntityNameChar(c byte) bool {
	return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9'
}

func isDigit(c byte, radix int) bool {
	switch {
	case c >= '0' && c <= '9':
		return radix == 10 || c-'0' < radix
	case c >= 'a' && c <= 'f':
		return radix == 16
	case c >= 'A' && c <= 'F':
		return radix == 16
	}
	return false
}

func parseRadix(s string, radix int) uint64 {
	var n uint64
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d uint64
		switch {
		case c >= '0' && c <= '9':
			d = uint64(c - '0')
		case c >= 'a' && c <= 'f':
			d = uint64(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = uint64(c-'A') + 10
		}
		n = n*uint64(radix) + d
	}
	return n
}
