package dom

import "strings"

// HTML5-ish tree construction.
//
// The implementation follows the HTML5 "in body" insertion mode closely enough
// for realistic documents: implied <html>/<head>/<body>, void elements, raw text
// elements, implied end tags, formatting element reconstruction and the
// adoption agency (simplified).

var voidElements = map[string]bool{
	"area": true, "base": true, "basefont": true, "bgsound": true, "br": true,
	"col": true, "embed": true, "frame": true, "hr": true, "img": true,
	"input": true, "keygen": true, "link": true, "meta": true, "param": true,
	"source": true, "track": true, "wbr": true,
}

// elements that close an open <p> when they start
var closesP = map[string]bool{
	"address": true, "article": true, "aside": true, "blockquote": true,
	"center": true, "details": true, "dialog": true, "dir": true, "div": true,
	"dl": true, "fieldset": true, "figcaption": true, "figure": true,
	"footer": true, "header": true, "hgroup": true, "main": true, "menu": true,
	"nav": true, "ol": true, "p": true, "section": true, "summary": true,
	"ul": true, "h1": true, "h2": true, "h3": true, "h4": true, "h5": true,
	"h6": true, "pre": true, "listing": true, "form": true, "li": true,
	"dt": true, "dd": true, "hr": true, "table": true,
}

// list of "special" elements used for the scope calculations
var special = map[string]bool{
	"address": true, "area": true, "article": true, "aside": true,
	"base": true, "basefont": true, "bgsound": true, "blockquote": true,
	"body": true, "br": true, "button": true, "caption": true, "center": true,
	"col": true, "colgroup": true, "dd": true, "dt": true, "embed": true,
	"fieldset": true, "figcaption": true, "figure": true, "footer": true,
	"form": true, "frame": true, "frameset": true, "h1": true, "h2": true,
	"h3": true, "h4": true, "h5": true, "h6": true, "head": true,
	"header": true, "hgroup": true, "hr": true, "html": true, "iframe": true,
	"legend": true, "li": true, "link": true, "listing": true, "main": true,
	"marquee": true, "menu": true, "meta": true, "nav": true, "noembed": true,
	"noframes": true, "noscript": true, "object": true, "ol": true, "p": true,
	"param": true, "plaintext": true, "pre": true, "script": true,
	"section": true, "select": true, "source": true, "style": true,
	"summary": true, "table": true, "tbody": true, "td": true, "template": true,
	"textarea": true, "tfoot": true, "th": true, "thead": true, "title": true,
	"tr": true, "track": true, "ul": true, "wbr": true, "xmp": true,
}

// formatting elements
var formatting = map[string]bool{
	"a": true, "b": true, "big": true, "code": true, "em": true, "font": true,
	"i": true, "nobr": true, "s": true, "small": true, "strike": true,
	"strong": true, "tt": true, "u": true,
}

var optEndTags = map[string]bool{
	"p": true, "li": true, "dt": true, "dd": true, "td": true, "th": true,
	"tr": true, "tbody": true, "thead": true, "tfoot": true, "option": true,
	"optgroup": true, "caption": true, "colgroup": true, "rt": true, "rp": true,
}

var tableSectionTags = map[string]bool{
	"caption": true, "colgroup": true, "col": true, "tbody": true, "tfoot": true,
	"thead": true, "tr": true, "td": true, "th": true,
}

type treeBuilder struct {
	doc      *Node
	stack    []*Node
	fmtList  []*Node
	head     *Node
	body     *Node
	mode     string
	ignoreLF bool
	frameset bool
}

func (b *treeBuilder) current() *Node {
	if len(b.stack) == 0 {
		return b.body
	}
	return b.stack[len(b.stack)-1]
}

func (b *treeBuilder) push(n *Node) {
	b.stack = append(b.stack, n)
}

func (b *treeBuilder) pop() *Node {
	n := b.stack[len(b.stack)-1]
	b.stack = b.stack[:len(b.stack)-1]
	return n
}

// hasInScope reports whether an element with the given tag is in scope,
// starting from the current node and stopping at special elements.
func (b *treeBuilder) hasInScope(tag string, extra map[string]bool) bool {
	for i := len(b.stack) - 1; i >= 0; i-- {
		t := b.stack[i].Tag
		if t == tag {
			return true
		}
		if special[t] || (extra != nil && extra[t]) {
			return false
		}
	}
	return false
}

var buttonScope = map[string]bool{
	"button": true, "marquee": true, "optgroup": true, "option": true,
	"select": true, "td": true, "th": true, "keygen": true, "label": true,
	"output": true, "mi": true, "mo": true, "mn": true, "ms": true,
	"mtext": true, "annotation-text": true, "foreignObject": true, "desc": true,
	"title": true,
}

func (b *treeBuilder) insert(n *Node) {
	b.current().appendChild(n)
}

func (b *treeBuilder) text(s string) {
	if s == "" {
		return
	}
	if b.ignoreLF {
		if s[0] == '\n' {
			s = s[1:]
		}
		b.ignoreLF = false
	}
	if s == "" {
		return
	}
	b.insert(newNode(NodeText, "").withText(s))
}

func (n *Node) withText(s string) *Node {
	n.Text = s
	return n
}

func (b *treeBuilder) comment(data string) {
	b.insert(newNode(NodeComment, "").withText(data))
}

func (b *treeBuilder) doctype(data string) {
	b.insert(newNode(NodeDoctype, "").withText(data))
}

// reconstruct inserts copies of the open active formatting elements.
func (b *treeBuilder) reconstruct() {
	// find the last element that is on the stack
	last := -1
	for i := len(b.fmtList) - 1; i >= 0; i-- {
		f := b.fmtList[i]
		if f == nil {
			break
		}
		if b.inStack(f) {
			last = i
			break
		}
	}
	if last < 0 {
		return
	}
	// clone the entries after last
	var clones []*Node
	for i := last + 1; i < len(b.fmtList); i++ {
		f := b.fmtList[i]
		if f == nil {
			break
		}
		clone := f.cloneShallow()
		b.current().appendChild(clone)
		b.push(clone)
		clones = append(clones, clone)
		b.fmtList[i] = clone
	}
	_ = clones
}

func (n *Node) cloneShallow() *Node {
	c := newNode(NodeElement, n.Tag)
	c.Attrs = map[string]string{}
	for k, v := range n.Attrs {
		c.Attrs[k] = v
	}
	c.AttrList = append([]Attr{}, n.AttrList...)
	return c
}

func (b *treeBuilder) inStack(n *Node) bool {
	for _, s := range b.stack {
		if s == n {
			return true
		}
	}
	return false
}

func (b *treeBuilder) indexOfStack(n *Node) int {
	for i, s := range b.stack {
		if s == n {
			return i
		}
	}
	return -1
}

// addFmt adds a formatting element to the list of active formatting elements.
func (b *treeBuilder) addFmt(n *Node) {
	// remove existing entries with the same tag name (per the spec this only
	// happens for the "noah ark" algorithm, simplified here)
	b.fmtList = append(b.fmtList, n)
}

// clearFmt removes formatting entries up to the last marker.
func (b *treeBuilder) clearFmt() {
	for i := len(b.fmtList) - 1; i >= 0; i-- {
		if b.fmtList[i] == nil {
			b.fmtList = b.fmtList[:i+1]
			return
		}
	}
	b.fmtList = b.fmtList[:0]
}

// closeP closes an open <p> element.
func (b *treeBuilder) closeP() {
	if !b.hasInScope("p", buttonScope) {
		return
	}
	b.generateImpliedEndTags("p")
	// pop until a p has been popped
	for len(b.stack) > 0 {
		n := b.pop()
		if n.Tag == "p" {
			break
		}
	}
}

// generateImpliedEndTags pops elements with optional end tags, except for the
// given tag name.
func (b *treeBuilder) generateImpliedEndTags(except string) {
	for len(b.stack) > 0 {
		n := b.current()
		if !optEndTags[n.Tag] || n.Tag == except {
			return
		}
		b.pop()
	}
}

func (b *treeBuilder) startTag(name string, tok token) {
	// raw text elements are handled by the tokenizer: push the element
	switch name {
	case "html":
		if b.mode == "inBody" {
			if b.hasInScope("template", nil) {
				b.insertElem(name, tok)
			}
			return
		}
		if b.mode == "afterHead" || b.mode == "inHead" {
			return
		}
		b.insertElem(name, tok)
		return
	case "head":
		return
	case "body":
		return
	}

	switch b.mode {
	case "inHead", "beforeHead":
		if !isHeadElement(name) {
			// fall out of the head
			if b.head != nil {
				b.popTo(b.head)
			}
			b.ensureBody()
			b.startTag(name, tok)
			return
		}
	case "afterHead":
		if !isHeadElement(name) {
			b.ensureBody()
			b.startTag(name, tok)
			return
		}
	case "inFrameset":
		return
	case "afterFrameset":
		return
	}

	// --- in body ---
	if b.frameset {
		return
	}
	switch name {
	case "address", "article", "aside", "blockquote", "center", "details",
		"dialog", "dir", "div", "dl", "fieldset", "figcaption", "figure",
		"footer", "header", "hgroup", "main", "menu", "nav", "ol", "p",
		"section", "summary", "ul":
		b.closeP()
		if cur := b.current(); special[cur.Tag] && inBlockList(cur.Tag) {
			b.pop()
		}
		b.insertElem(name, tok)
	case "h1", "h2", "h3", "h4", "h5", "h6":
		b.closeP()
		if cur := b.current(); cur.Tag == name || (len(cur.Tag) == 2 && cur.Tag[0] == 'h' && cur.Tag[1] >= '1' && cur.Tag[1] <= '6') {
			b.pop()
		}
		b.insertElem(name, tok)
	case "pre", "listing", "form":
		if name == "form" {
			if b.hasInScope("form", nil) {
				return
			}
		}
		b.closeP()
		b.insertElem(name, tok)
		b.ignoreLF = true
	case "li":
		b.closeP()
		if cur := b.current(); cur.Tag == "li" {
			b.generateImpliedEndTags("li")
			for len(b.stack) > 0 && b.pop().Tag != "li" {
			}
		}
		if b.hasInScope("p", nil) || b.hasInScope("address", nil) || b.hasInScope("div", nil) || b.hasInScope("dl", nil) {
			// parse error, but we still insert (matches observed behaviour)
		}
		b.insertElem(name, tok)
		b.clearFmt()
	case "dt", "dd":
		b.closeP()
		if cur := b.current(); cur.Tag == name || cur.Tag == "dd" || cur.Tag == "dt" {
			b.generateImpliedEndTags("")
			for len(b.stack) > 0 && b.pop().Tag != "dd" && b.pop().Tag != "dt" {
				break
			}
		}
		b.insertElem(name, tok)
		b.clearFmt()
	case "hr", "image", "area", "base", "basefont", "bgsound", "br", "col",
		"embed", "keygen", "link", "meta", "param", "source", "track", "wbr",
		"frame", "input", "img":
		if name == "image" {
			name = "img"
		}
		if name == "hr" {
			b.closeP()
		}
		b.reconstruct()
		n := newNode(NodeElement, name)
		for _, a := range tok.attrList {
			n.setAttr(a.Name, a.Value)
		}
		b.insert(n)
		b.ignoreLF = (name == "hr")
	case "noscript", "textarea", "title", "style", "script", "xmp", "iframe",
		"noembed", "noframes", "plaintext", "template":
		b.reconstruct()
		b.insertElem(name, tok)
		if name == "xmp" || name == "listing" {
			b.ignoreLF = true
		}
	case "select", "optgroup", "option":
		if name == "select" {
			b.reconstruct()
			if cur := b.current(); cur.Tag == "option" || cur.Tag == "optgroup" || cur.Tag == "select" || cur.Tag == "input" || cur.Tag == "keygen" || cur.Tag == "textarea" || cur.Tag == "script" || cur.Tag == "style" || cur.Tag == "template" {
				b.pop()
			}
			b.insertElem(name, tok)
			return
		}
		if cur := b.current(); cur.Tag == "option" {
			b.pop()
		}
		b.reconstruct()
		b.insertElem(name, tok)
	case "caption", "col", "colgroup", "tbody", "tfoot", "thead", "td", "th", "tr":
		if b.hasInScope("table", nil) {
			// simplified: insert into the current node
		}
		b.insertElem(name, tok)
	case "button", "marquee", "object", "template":
		if name == "button" && b.hasInScope("button", nil) {
			b.anyOtherEndTag("button")
		}
		b.reconstruct()
		b.insertElem(name, tok)
		if name == "button" || name == "marquee" || name == "object" {
			b.fmtList = append(b.fmtList, nil)
		}
	case "nobr":
		b.reconstruct()
		b.insertElem(name, tok)
	default:
		if formatting[name] {
			// adoption agency (simplified): close an open element of the same
			// name before inserting
			if b.hasInScope(name, nil) {
				b.anyOtherEndTag(name)
			}
			b.reconstruct()
			n := b.insertElem(name, tok)
			b.addFmt(n)
			if tok.selfClosing {
				b.pop()
			}
			return
		}
		b.reconstruct()
		b.insertElem(name, tok)
	}
}

var blockListForPop = map[string]bool{
	"address": true, "article": true, "aside": true, "blockquote": true,
	"center": true, "details": true, "dialog": true, "dir": true, "div": true,
	"dl": true, "fieldset": true, "figcaption": true, "figure": true,
	"footer": true, "header": true, "hgroup": true, "main": true, "menu": true,
	"nav": true, "ol": true, "p": true, "section": true, "summary": true,
	"ul": true,
}

func inBlockList(t string) bool { return blockListForPop[t] }

func isHeadElement(name string) bool {
	switch name {
	case "title", "meta", "link", "base", "style", "script", "template",
		"noscript", "basefont", "bgsound", "noframes", "head":
		return true
	}
	return false
}

func (b *treeBuilder) insertElem(name string, tok token) *Node {
	n := newNode(NodeElement, name)
	for _, a := range tok.attrList {
		n.setAttr(a.Name, a.Value)
	}
	n.SelfClosing = tok.selfClosing
	b.insert(n)
	if !voidElements[name] && !tok.selfClosing {
		b.push(n)
	}
	return n
}

func (b *treeBuilder) popTo(n *Node) {
	for len(b.stack) > 0 {
		if b.pop() == n {
			return
		}
	}
}

func (b *treeBuilder) ensureHead() {
	if b.head == nil {
		h := newNode(NodeElement, "head")
		b.current().appendChild(h)
		b.head = h
		b.push(h)
		b.mode = "inHead"
	}
}

func (b *treeBuilder) ensureBody() {
	if b.body == nil {
		b.ensureHead()
		// leave the head
		if len(b.stack) > 0 && b.stack[len(b.stack)-1] == b.head {
			b.pop()
		}
		bd := newNode(NodeElement, "body")
		b.current().appendChild(bd)
		b.body = bd
		b.push(bd)
		b.mode = "inBody"
	}
}

func (b *treeBuilder) endTag(name string) {
	switch name {
	case "html":
		if len(b.stack) > 0 && b.current().Tag != "html" {
			b.anyOtherEndTag(name)
		}
		return
	case "head", "body":
		return
	case "br":
		return
	}
	if b.frameset {
		return
	}
	b.anyOtherEndTag(name)
}

// anyOtherEndTag implements the "any other end tag" rules.
func (b *treeBuilder) anyOtherEndTag(name string) {
	// find the nearest element with that name in the stack
	idx := -1
	for i := len(b.stack) - 1; i >= 0; i-- {
		if b.stack[i].Tag == name {
			idx = i
			break
		}
	}
	if idx < 0 {
		// not found: ignore (unless it is a formatting element)
		return
	}
	b.generateImpliedEndTags(name)
	// pop until the element is popped
	for len(b.stack) > 0 {
		n := b.pop()
		if n.Tag == name {
			break
		}
	}
	// remove it from the list of active formatting elements
	for i, f := range b.fmtList {
		if f == nil {
			break
		}
		if f.Tag == name && !b.inStack(f) {
			b.fmtList = append(b.fmtList[:i], b.fmtList[i+1:]...)
			break
		}
	}
}

// Parse parses the given HTML into a document node.
func Parse(src string) *Node {
	doc := newNode(NodeDocument, "")
	doc.appendChild(newNode(NodeElement, "#document-fragment"))
	root := doc.Children[0]
	b := &treeBuilder{doc: root, mode: "initial"}
	tz := &tokenizer{src: src}
	var pending []token
	for {
		var tok token
		var ok bool
		if len(pending) > 0 {
			tok = pending[0]
			pending = pending[1:]
			ok = true
		} else {
			tok, ok = tz.next()
		}
		if !ok {
			break
		}
		switch tok.kind {
		case tkText:
			b.handleText(tok.text)
		case tkComment:
			b.handleComment(tok.data)
		case tkDoctype:
			b.handleDoctype(tok.data)
		case tkStart:
			b.handleStart(tok)
		case tkEnd:
			b.handleEnd(tok.data)
		}
	}
	return doc
}

func (b *treeBuilder) handleText(s string) {
	if b.mode == "initial" || b.mode == "beforeHead" || b.mode == "afterHead" {
		b.beforeBody()
		b.handleText(s)
		return
	}
	if b.mode == "beforeHead" {
		b.ensureHead()
	}
	b.text(s)
}

