// blockTags are the elements that produce a block in the output.
var blockTags = map[string]bool{
	"p": true, "h1": true, "h2": true, "h3": true, "h4": true, "h5": true,
	"h6": true, "ul": true, "ol": true, "dl": true, "dt": true, "dd": true,
	"li": true, "blockquote": true, "pre": true, "hr": true, "div": true,
	"address": true, "main": true, "nav": true, "aside": true, "header": true,
	"footer": true, "section": true, "article": true, "figure": true,
	"figcaption": true, "details": true, "summary": true, "form": true,
	"fieldset": true, "table": true,
}

// elements whose content is wrapped in delimiters (so the content is not at a
// line start)
var delimitedTags = map[string]bool{
	"b": true, "strong": true, "em": true, "i": true, "code": true,
	"kbd": true, "tt": true, "samp": true, "var": true, "a": true,
	"s": true, "del": true, "strike": true,
}

// codeContentTags render with backticks
var codeTags = map[string]bool{
	"code": true, "kbd": true, "tt": true, "samp": true, "var": true,
}

func isBlockNode(n *dom.Node) bool {
	if n.Type != dom.NodeElement {
		return false
	}
	if n.Tag == "table" {
		return true
	}
	return blockTags[n.Tag]
}

// ---------------------------------------------------------------------------
// state
// ---------------------------------------------------------------------------

type state struct {
	lineStart bool // the next content is at the start of a line
	alt       bool // escaping image alt text
	code      bool // inside a code block content
	delim     string // current emphasis delimiters ("" when none)
}

func (c *Converter) newState(lineStart bool) *state {
	return &state{lineStart: lineStart}
}

// ---------------------------------------------------------------------------
// main entry
// ---------------------------------------------------------------------------

func (c *Converter) Convert(doc *dom.Node) string {
	var children []*dom.Node
	var walk func(*dom.Node)
	walk = func(n *dom.Node) {
		if n.Type == dom.NodeElement && n.Tag == "body" {
			children = n.Children
			return
		}
		for _, ch := range n.Children {
			walk(ch)
		}
	}
	walk(doc)
	if children == nil {
		children = doc.Children
	}
	blocks := c.convChildren(children, c.newState(true))
	return strings.Join(c.assemble(blocks), blockSep)
}

// assemble normalises hard breaks inside each block and splits blocks where
// needed.
func (c *Converter) assemble(blocks []string) []string {
	out := []string{}
	for _, b := range blocks {
		out = append(out, c.normalizeBlock(b)...)
	}
	// drop empty blocks
	res := []string{}
	for _, b := range out {
		if b == "" {
			continue
		}
		res = append(res, b)
	}
	return res
}

func isBreak(r rune) bool { return r == breakMarker }

func isASCIISpace(r rune) bool {
	return r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\v' || r == '\f'
}

// normalizeBlock collapses whitespace, handles hard breaks and trims.
func (c *Converter) normalizeBlock(s string) []string {
	if s == "" {
		return []string{""}
	}
	// collapse runs of ascii whitespace (break marker is not whitespace)
	var sb strings.Builder
	prevWS := false
	for _, r := range s {
		if isASCIISpace(r) {
			if !prevWS {
				sb.WriteRune(' ')
			}
			prevWS = true
			continue
		}
		prevWS = false
		sb.WriteRune(r)
	}
	s = sb.String()
	// handle breaks
	var out []string
	var cur strings.Builder
	i := 0
	runes := []rune(s)
	n := len(runes)
	hasContent := false
	pending := 0
	flush := func(count int) {
		if !hasContent {
			return
		}
		if count == 1 {
			cur.WriteString(hardBreak)
		} else {
			// multiple breaks -> block boundary
			out = append(out, strings.TrimSpace(strings.Trim(cur.String(), "\n")))
			cur.Reset()
			hasContent = false
		}
	}
	for i < n {
		r := runes[i]
		if r == breakMarker {
			// gather a run of breaks (with optional whitespace between)
			j := i
			count := 0
			for j < n {
				if runes[j] == breakMarker {
					count++
					j++
					for j < n && isASCIISpace(runes[j]) {
						j++
					}
					continue
				}
				break
			}
			i = j
			flush(count)
			continue
		}
		if isASCIISpace(r) {
			// whitespace: only emit if content follows and no pending break
			j := i
			for j < n && isASCIISpace(runes[j]) {
				j++
			}
			if j < n && runes[j] != breakMarker && hasContent {
				cur.WriteRune(' ')
			}
			i = j
			continue
		}
		cur.WriteRune(r)
		hasContent = true
		i++
	}
	out = append(out, cur.String())
	// trim
	res := []string{}
	for _, b := range out {
		b = strings.Trim(b, " \t\n\v\f\rÂ\u00a0\u2028\u2029\u3000")
		if b == "" {
			continue
		}
		res = append(res, b)
	}
	return res
}

func trimSpaceAll(s string) string {
	return strings.TrimFunc(s, func(r rune) bool {
		return isASCIISpace(r) || r == 0xa0 || r == 0x2028 || r == 0x2029 || r == 0x3000
	})
}

func collapseText(s string) string {
	var sb strings.Builder
	prevWS := false
	for _, r := range s {
		if isASCIISpace(r) {
			if !prevWS {
				sb.WriteRune(' ')
			}
			prevWS = true
			continue
		}
		prevWS = false
		sb.WriteRune(r)
	}
	return sb.String()
}

// ---------------------------------------------------------------------------
// children rendering
// ---------------------------------------------------------------------------

// convChildren renders a list of nodes into blocks.
func (c *Converter) convChildren(nodes []*dom.Node, st *state) []string {
	blocks := []string{}
	cur := strings.Builder{} // current inline buffer
	curHas := false
	flush := func() {
		s := cur.String()
		cur.Reset()
		curHas = false
		if s == "" {
			return
		}
		blocks = append(blocks, s)
	}
	for _, n := range nodes {
		if n.Type == dom.NodeText {
			t := collapseText(n.Text)
			if t == "" {
				continue
			}
			cur.WriteString(c.escape(t, st))
			st.lineStart = false
			curHas = true
			continue
		}
		if n.Type == dom.NodeComment || n.Type == dom.NodeDoctype {
			continue
		}
		// element
		if n.Tag == "br" {
			cur.WriteRune(breakMarker)
			st.lineStart = true
			curHas = true
			continue
		}
		if isBlockNode(n) {
			// flush the current inline content as a block
			flush()
			st.lineStart = st.lineStart || true
			sub := c.convNode(n, c.newState(!delimitedTags[n.Tag] && n.Tag != "blockquote" && n.Tag != "pre"))
			blocks = append(blocks, sub...)
			// after a block the next inline content is at a line start
			st.lineStart = false
			continue
		}
		// inline element
		sub := c.convNode(n, st)
		if len(sub) == 0 {
			continue
		}
		// merge the inline element's blocks: the first goes into the current
		// buffer, the rest become blocks
		cur.WriteString(sub[0])
		curHas = true
		if len(sub) > 1 {
			flush()
			for i := 1; i < len(sub)-1; i++ {
				blocks = append(blocks, sub[i])
			}
			cur.WriteString(sub[len(sub)-1])
			curHas = true
		}
	}
	flush()
	return blocks
}

// convNode renders a single element node into blocks.
func (c *Converter) convNode(n *dom.Node, st *state) []string {
	if n.Type == dom.NodeText {
		return []string{c.escape(collapseText(n.Text), st)}
	}
	if n.Type != dom.NodeElement {
		return nil
	}
	switch n.Tag {
	case "p":
		sub := c.convChildren(n.Children, c.newState(true))
		return sub
	case "h1", "h2", "h3", "h4", "h5", "h6":
		inner := c.inlineContent(n.Children, c.newState(false))
		inner = strings.TrimFunc(inner, func(r rune) bool { return isASCIISpace(r) || r == 0xa0 })
		inner = strings.ReplaceAll(inner, string(breakMarker), " ")
		if inner == "" {
			return nil
		}
		hashes := ""
		for _, r := range n.Tag[1:] {
			_ = r
		}
		level := len(n.Tag)
		for i := 1; i < level; i++ {
			hashes += "#"
		}
		return []string{hashes + " " + inner}
	case "blockquote":
		sub := c.convChildren(n.Children, c.newState(false))
		var res []string
		for _, b := range sub {
			res = append(res, c.prefixLines(b, "> "))
		}
		return res
	case "hr":
		return []string{"* * *"}
	case "pre":
		content := c.codeContent(n)
		return []string{"```\n" + content + "\n```"}
	case "ul":
		return c.convList(n, false)
	case "ol":
		return c.convList(n, true)
	case "table":
		if c.hasTable {
			return c.convTable(n)
		}
		sub := c.convChildren(n.Children, c.newState(true))
		res := []string{}
		for _, b := range sub {
			res = append(res, b)
		}
		return res
	case "dt", "dd", "li", "figcaption", "summary", "caption", "col",
		"colgroup", "optgroup", "option", "legend", "output", "label",
		"button", "select", "fieldset", "form", "details", "figure",
		"address", "center", "main", "nav", "aside", "header", "footer",
		"section", "article", "dl":
		if n.Tag == "li" {
			return c.convChildren(n.Children, c.newState(true))
		}
		sub := c.convChildren(n.Children, c.newState(true))
		return sub
	case "div":
		sub := c.convChildren(n.Children, c.newState(true))
		return sub
	case "br":
		return []string{hardBreak}
	case "img":
		return c.convImage(n)
	case "a":
		return c.convLink(n)
	default:
		if codeTags[n.Tag] {
			return c.convCode(n)
		}
		if n.Tag == "b" || n.Tag == "strong" {
			return c.convEmphasis(n, c.opts.StrongDelimiter)
		}
		if n.Tag == "em" || n.Tag == "i" {
			return c.convEmphasis(n, "*")
		}
		if c.hasStrike && (n.Tag == "s" || n.Tag == "del" || n.Tag == "strike") {
			return c.convEmphasis(n, "~~")
		}
		// plain inline container
		return c.convChildren(n.Children, st)
	}
}

// inlineContent renders children as a single inline string (no block splits).
func (c *Converter) inlineContent(nodes []*dom.Node, st *state) string {
	var sb strings.Builder
	var walk func([]*dom.Node)
	walk = func(ns []*dom.Node) {
		for _, n := range ns {
			if n.Type == dom.NodeText {
				sb.WriteString(c.escape(collapseText(n.Text), st))
				st.lineStart = false
				continue
			}
			if n.Type != dom.NodeElement {
				continue
			}
			if n.Tag == "br" {
				sb.WriteRune(breakMarker)
				st.lineStart = true
				continue
			}
			if isBlockNode(n) {
				// flatten block content
				walk(n.Children)
				continue
			}
			walk(n.Children)
		}
	}
	walk(nodes)
	return sb.String()
}

func (c *Converter) prefixLines(s, prefix string) string {
	lines := strings.Split(s, "\n")
	for i, l := range lines {
		lines[i] = prefix + l
	}
	return strings.Join(lines, "\n")
}

func (c *Converter) convList(n *dom.Node, ordered bool) []string {
	items := []string{}
	for _, ch := range n.Children {
		if ch.Type != dom.NodeElement {
			continue
		}
		if ch.Tag == "li" {
			items = append(items, ch)
		} else if ch.Tag == "ul" || ch.Tag == "ol" {
			// nested list without a li: append its items
			items = append(items, c.convList(ch, ch.Tag == "ol")...)
		}
	}
	out := []string{}
	for i, it := range items {
		marker := "- "
		if ordered {
			marker = itoa(i+1) + ". "
		}
		sub := c.convChildren(it.Children, c.newState(true))
		subBlocks := c.assemble(sub)
		if len(subBlocks) == 0 {
			continue
		}
		first := subBlocks[0]
		rest := []string{}
		for _, b := range subBlocks[1:] {
			rest = append(rest, c.indentLines(b, "  "))
		}
		s := marker + first
		for _, r := range rest {
			s += "\n" + r
		}
		out = append(out, s)
	}
	return out
}

func itoa(i int) string {
	if i == 0 {
		return "0"
	}
	neg := false
	if i < 0 {
		neg = true
		i = -i
	}
	var b []byte
	for i > 0 {
		b = append([]byte{byte('0' + i%10)}, b...)
		i /= 10
	}
	if neg {
		return "-" + string(b)
	}
	return string(b)
}

func (c *Converter) indentLines(s, prefix string) string {
	lines := strings.Split(s, "\n")
	for i, l := range lines {
		if l == "" {
			lines[i] = strings.TrimRight(prefix, " ")
		} else {
			lines[i] = prefix + l
		}
	}
	return strings.Join(lines, "\n")
}

// convImage renders an <img> element.
func (c *Converter) convImage(n *dom.Node) []string {
	src := n.Get("src")
	if src == "" {
		return nil
	}
	href := c.resolveURL(src)
	if href == "" {
		return nil
	}
	alt := c.escapeAlt(collapseText(n.Get("alt")))
	title := n.Get("title")
	s := "![" + alt + "](" + href
	if title != "" {
		s += " \"" + title + "\""
	}
	s += ")"
	return []string{s}
}

func (c *Converter) convLink(n *dom.Node) []string {
	href := c.resolveURL(n.Get("href"))
	title := n.Get("title")
	sub := c.convChildren(n.Children, c.newState(false))
	if len(sub) == 0 {
		sub = []string{""}
	}
	// the link content is a single inline block
	content := strings.Join(c.assemble(sub), blockSep)
	content, lead, trail := c.trimForDelim(content)
	if content == "" {
		content = ""
	}
	s := lead + "[" + content + "](" + href
	if title != "" {
		s += " \"" + title + "\""
	}
	s += ")" + trail
	return []string{s}
}

// trimForDelim removes the leading/trailing whitespace and returns it.
func (c *Converter) trimForDelim(s string) (string, string, string) {
	// trailing first
	trail := ""
	lead := ""
	for len(s) > 0 {
		r := rune(s[len(s)-1])
		if r < 128 && (r == ' ' || r == '\t' || r == '\n' || r == '\r') {
			trail = " " + trail
			s = s[:len(s)-1]
			continue
		}
		break
	}
	for len(s) > 0 {
		r := rune(s[0])
		if r < 128 && (r == ' ' || r == '\t' || r == '\n' || r == '\r') {
			lead += " "
			s = s[1:]
			continue
		}
		break
	}
	return s, lead, trail
}

// convCode renders inline code elements.
func (c *Converter) convCode(n *dom.Node) []string {
	content := c.codeContent(n)
	content = collapseText(content)
	content = trimSpaceAll(content)
	content = strings.ReplaceAll(content, string(breakMarker), " ")
	content = strings.ReplaceAll(content, "\n", " ")
	return []string{"`" + content + "`"}
}

// convEmphasis renders emphasis-like elements (b/strong/em/i/s/...).
func (c *Converter) convEmphasis(n *dom.Node, delim string) []string {
	return c.convDelimited(n.Children, delim, c.newState(false))
}

// convDelimited partitions children at block boundaries and wraps each
// segment in the delimiters.
func (c *Converter) convDelimited(children []*dom.Node, delim string, st *state) []string {
	segs := c.partition(children)
	blocks := []string{}
	for _, seg := range segs {
		if seg.block != nil {
			b := c.convNode(seg.block, c.newState(true))
			for _, x := range b {
				blocks = append(blocks, delim+x+delim)
			}
			continue
		}
		if seg.breaks >= 2 {
			// paragraph break handled by the block join
			continue
		}
		content := c.inlineContent(seg.nodes, st)
		blocks = append(blocks, c.wrapLines(content, delim, st))
	}
	return blocks
}

type segment struct {
	nodes  []*dom.Node
	block  *dom.Node
	breaks int
}

// partition splits children into segments at block boundaries and at runs of
// two or more <br> elements.
func (c *Converter) partition(children []*dom.Node) []*segment {
	segs := []*segment{}
	cur := &segment{}
	i := 0
	for i < len(children) {
		n := children[i]
		if n.Type == dom.NodeElement && n.Tag == "br" {
			// count consecutive brs (ignoring whitespace-only text)
			j := i
			count := 0
			for j < len(children) {
				x := children[j]
				if x.Type == dom.NodeElement && x.Tag == "br" {
					count++
					j++
					// skip whitespace-only text
					for j < len(children) {
						y := children[j]
						if y.Type == dom.NodeText && collapseText(y.Text) == "" {
							j++
							continue
						}
						if y.Type == dom.NodeElement && isVoidInline(y.Tag) {
							j++
							continue
						}
						break
					}
					continue
				}
				break
			}
			if count >= 2 {
				if len(cur.nodes) > 0 {
					segs = append(segs, cur)
					cur = &segment{}
				}
				i = j
				continue
			}
			for k := i; k < j; k++ {
				cur.nodes = append(cur.nodes, children[k])
			}
			i = j
			continue
		}
		if isBlockNode(n) {
			if len(cur.nodes) > 0 {
				segs = append(segs, cur)
				cur = &segment{}
			}
			segs = append(segs, &segment{block: n})
			i++
			continue
		}
		cur.nodes = append(cur.nodes, n)
		i++
	}
	if len(cur.nodes) > 0 {
		segs = append(segs, cur)
	}
	return segs
}

func isVoidInline(tag string) bool {
	switch tag {
	case "wbr", "img":
		return true
	}
	return false
}

// wrapLines splits the content at hard breaks and wraps each line.
func (c *Converter) wrapLines(content, delim string, st *state) string {
	// remove the leading/trailing whitespace and remember it
	lead := ""
	trail := ""
	for len(content) > 0 {
		r := rune(content[len(content)-1])
		if r == ' ' || r == '\t' {
			trail = " " + trail
			content = content[:len(content)-1]
			continue
		}
		break
	}
	for len(content) > 0 {
		r := rune(content[0])
		if r == ' ' || r == '\t' {
			lead += " "
			content = content[1:]
			continue
		}
		break
	}
	if content == "" {
		return lead + trail
	}
	parts := strings.Split(content, string(breakMarker))
	var sb strings.Builder
	sb.WriteString(lead)
	for i, p := range parts {
		if i > 0 {
			sb.WriteString(hardBreak)
		}
		p = strings.TrimFunc(p, func(r rune) bool { return isASCIISpace(r) })
		if i > 0 && i < len(parts)-1 {
			p = strings.TrimFunc(p, func(r rune) bool { return isASCIISpace(r) })
		}
		sb.WriteString(delim + p + delim)
	}
	sb.WriteString(trail)
	return sb.String()
}

// ---------------------------------------------------------------------------
// escaping
// ---------------------------------------------------------------------------

func (c *Converter) escape(s string, st *state) string {
	if st.code {
		return s
	}
	if st.alt {
		return escapeAlt(s)
	}
	if c.opts.EscapeMode == "disabled" {
		return escapeHTML(s)
	}
	return escapeSmart(s, st.lineStart)
}

func escapeAlt(s string) string {
	var sb strings.Builder
	for _, r := range s {
		switch r {
		case '[', ']':
			sb.WriteRune('\\')
			sb.WriteRune(r)
		default:
			sb.WriteRune(r)
		}
	}
	return sb.String()
}

func escapeHTML(s string) string {
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	return s
}

// escapeSmart applies the "smart" escaping rules.
func escapeSmart(s string, lineStart bool) string {
	runes := []rune(s)
	n := len(runes)
	var sb strings.Builder
	for i := 0; i < n; i++ {
		r := runes[i]
		next := rune(0)
		if i+1 < n {
			next = runes[i+1]
		}
		need := false
		switch r {
		case '\\':
			need = true
		case '`':
			need = true
		case '*':
			need = !isASCIISpace(next) && next != 0
		case '_':
			need = !isASCIISpace(next) && next != 0
		case '#', '-', '+':
			if lineStart && (isASCIISpace(next) || next == 0) {
				need = true
			}
		case '.', ')':
			if lineStart && (isASCIISpace(next) || next == 0) && allDigitsBefore(runes, i) {
				need = true
			}
		case '[':
			need = hasCharAfter(runes, i, ']')
		case '<':
			sb.WriteString("&lt;")
			continue
		case '>':
			sb.WriteString("&gt;")
			continue
		}
		if need {
			sb.WriteRune('\\')
		}
		sb.WriteRune(r)
	}
	return sb.String()
}

func allDigitsBefore(runes []rune, i int) bool {
	if i == 0 {
		return false
	}
	for j := 0; j < i; j++ {
		if runes[j] < '0' || runes[j] > '9' {
			return false
		}
	}
	return true
}

func hasCharAfter(runes []rune, from int, target rune) bool {
	for j := from + 1; j < len(runes); j++ {
		if runes[j] == target {
			return true
		}
	}
	return false
}
