package converter

import (
	"strconv"
	"strings"

	"html2markdown/internal/dom"
)

// resolveURL resolves a relative URL against the configured domain.
func (c *Converter) resolveURL(raw string) string {
	if raw == "" {
		return ""
	}
	if c.domain == nil {
		return raw
	}
	u, err := urlParse(raw)
	if err != nil {
		return raw
	}
	return c.domain.ResolveReference(u).String()
}

func (c *Converter) convText(n *dom.Node, st *state) string {
	t := collapseText(n.Text)
	if t == "" {
		return ""
	}
	return c.escape(t, st)
}

// codeContent renders the children of a pre/code element in "code" mode.
func (c *Converter) codeContent(n *dom.Node) string {
	s := c.codeContentChildren(n.Children)
	s = strings.TrimSuffix(s, "\n")
	return s
}

func (c *Converter) codeContentChildren(children []*dom.Node) string {
	var sb strings.Builder
	for _, n := range children {
		if n.Type == dom.NodeText {
			sb.WriteString(n.Text)
			continue
		}
		if n.Type != dom.NodeElement {
			continue
		}
		switch n.Tag {
		case "div":
			sb.WriteString("\n")
			sb.WriteString(c.codeContentChildren(n.Children))
		case "h1", "h2", "h3", "h4", "h5", "h6":
			sb.WriteString(c.codeContentChildren(n.Children))
			sb.WriteString("\n")
		case "blockquote":
			sb.WriteString(" \"")
			sb.WriteString(c.codeContentChildren(n.Children))
			sb.WriteString("\" ")
		case "br":
			sb.WriteString("\n")
		case "script", "style", "textarea", "template", "noscript", "title",
			"iframe", "noembed", "noframes", "plaintext":
			// dropped
		default:
			sb.WriteString(c.codeContentChildren(n.Children))
		}
	}
	return sb.String()
}

// ---------------------------------------------------------------------------
// table plugin
// ---------------------------------------------------------------------------

type trow struct {
	nodes []*dom.Node // tr elements
}

type cellInfo struct {
	node    *dom.Node
	col     int
	row     int
	colSpan int
	rowSpan int
}

func (c *Converter) tableRows(n *dom.Node) (header *dom.Node, rows []*dom.Node, caption *dom.Node) {
	first := true
	var walk func(*dom.Node)
	walk = func(t *dom.Node) {
		for _, ch := range t.Children {
			if ch.Type != dom.NodeElement {
				continue
			}
			switch ch.Tag {
			case "caption":
				if caption == nil {
					caption = ch
				}
			case "colgroup", "col":
				// ignored
			case "thead":
				walk(ch)
			case "tbody", "tfoot":
				walk(ch)
			case "tr":
				if first {
					first = false
					if inThead(ch) {
						header = ch
					} else if c.opts.HeaderPromotion || hasTh(ch) {
						header = ch
					}
					rows = append(rows, ch)
					continue
				}
				rows = append(rows, ch)
			default:
				walk(ch)
			}
		}
	}
	walk(n)
	return header, rows, caption
}

var theadNodes = map[*dom.Node]bool{}

func inThead(tr *dom.Node) bool {
	for _, r := range theadNodes {
		if r == tr {
			return true
		}
	}
	return false
}

func hasTh(tr *dom.Node) bool {
	for _, ch := range tr.Children {
		if ch.Type == dom.NodeElement && (ch.Tag == "th" || ch.Tag == "td" && ch.Get("headers") != "") {
			return ch.Tag == "th"
		}
	}
	return false
}

// convTable renders a table element.
func (c *Converter) convTable(n *dom.Node) []string {
	if strings.EqualFold(n.Get("role"), "presentation") && !c.opts.PresentationTables {
		return c.tableFallback(n)
	}
	header, rows, caption := c.tableRows(n)
	// build the grid
	grid := map[[2]int]*dom.Node{}
	spans := map[[2]int]*dom.Node{}
	maxCol := 0
	rowCount := len(rows)
	occupied := map[int]map[int]bool{} // row -> col -> occupied
	getOcc := func(r int) map[int]bool {
		if occupied[r] == nil {
			occupied[r] = map[int]bool{}
		}
		return occupied[r]
	}
	rowSpanExtra := 0
	for r, tr := range rows {
		col := 0
		for _, ch := range tr.Children {
			if ch.Type != dom.NodeElement {
				continue
			}
			if ch.Tag != "td" && ch.Tag != "th" {
				continue
			}
			cs := parseSpan(ch.Get("colspan"))
			rs := parseSpan(ch.Get("rowspan"))
			for getOcc(r)[col] {
				col++
			}
			for i := 0; i < cs; i++ {
				for j := 0; j < rs; j++ {
					rr := r + j
					cc := col + i
					if getOcc(rr)[cc] {
						continue
					}
					getOcc(rr)[cc] = true
					if j == 0 && i == 0 {
						grid[[2]int{rr, cc}] = ch
					} else {
						spans[[2]int{rr, cc}] = ch
					}
					if rr+1 > rowCount+rowSpanExtra {
						rowSpanExtra = rr + 1 - rowCount
					}
					if cc+1 > maxCol {
						maxCol = cc + 1
					}
				}
			}
			col += cs
		}
	}
	totalRows := rowCount + rowSpanExtra
	if maxCol == 0 {
		maxCol = 1
	}
	// header
	headerCells := make([]string, maxCol)
	if header != nil {
		hcells := cellsOf(header)
		_ = hcells
	}
	// render the header cells
	var headerMd []string
	if header != nil {
		hc := headerChildren(header, maxCol)
		headerMd = hc
	} else {
		headerMd = make([]string, maxCol)
	}
	// body rows
	bodyRows := make([][]string, totalRows)
	for r := 0; r < totalRows; r++ {
		bodyRows[r] = make([]string, maxCol)
	}
	fallback := false
	for r, tr := range rows {
		// gather the cells in column order
		cells := make([]*dom.Node, 0)
		for _, ch := range tr.Children {
			if ch.Type == dom.NodeElement && (ch.Tag == "td" || ch.Tag == "th") {
				cells = append(cells, ch)
			}
		}
		ci := 0
		for cc := 0; cc < maxCol; cc++ {
			if spans[[2]int{r, cc}] != nil {
				// mirrored/empty cell
				sp := spans[[2]int{r, cc}]
				bodyRows[r][cc] = cellMarkdown(sp, c, r, cc, true)
				continue
			}
			if grid[[2]int{r, cc}] != nil {
				m := cellMarkdown(grid[[2]int{r, cc}], c, r, cc, false)
				bodyRows[r][cc] = m
				if strings.Contains(m, "\n") {
					fallback = true
				}
			}
			_ = ci
		}
	}
	if header != nil {
		for cc, m := range headerMd {
			if strings.Contains(m, "\n") {
				fallback = true
			}
		}
	}
	if fallback {
		return c.tableFallback(n)
	}
	// padding
	widths := make([]int, maxCol)
	for cc := 0; cc < maxCol; cc++ {
		w := len(headerMd[cc])
		for r := 0; r < totalRows; r++ {
			if l := visibleLen(bodyRows[r][cc]); l > w {
				w = l
			}
		}
		widths[cc] = w
	}
	pad := c.opts.CellPadding
	line := func(cells []string, isSep bool) string {
		var sb strings.Builder
		for cc := 0; cc < maxCol; cc++ {
			content := ""
			if !isSep {
				content = cells[cc]
			}
			switch pad {
			case "aligned":
				if isSep {
					sb.WriteString("|" + strings.Repeat("-", widths[cc]+2))
				} else {
					sb.WriteString("| " + padTo(content, widths[cc]) + " ")
				}
			case "minimal":
				if isSep {
					sb.WriteString("|---")
				} else {
					sb.WriteString("| " + content + " ")
				}
			default: // none
				if isSep {
					sb.WriteString("|---")
				} else {
					sb.WriteString("|" + content)
				}
			}
		}
		sb.WriteString("|")
		return sb.String()
	}
	// skip empty rows
	var out []string
	if c.opts.SkipEmptyRows {
		kept := make([][]string, 0, totalRows)
		for r := 0; r < totalRows; r++ {
			allEmpty := true
			for cc := 0; cc < maxCol; cc++ {
				if bodyRows[r][cc] != "" {
					allEmpty = false
					break
				}
			}
			if !allEmpty {
				kept = append(kept, bodyRows[r])
			}
		}
		out = make([]string, 0, len(kept)+2)
		out = append(out, line(headerMd, false))
		out = append(out, line(nil, true))
		for _, r := range kept {
			out = append(out, line(r, false))
		}
	} else {
		out = make([]string, 0, totalRows+2)
		out = append(out, line(headerMd, false))
		out = append(out, line(nil, true))
		for r := 0; r < totalRows; r++ {
			out = append(out, line(bodyRows[r], false))
		}
	}
	res := []string{strings.Join(out, "\n")}
	if caption != nil {
		cap := c.convChildren(caption.Children, c.newState(true))
		res = append(res, cap...)
	}
	return res
}

func parseSpan(s string) int {
	if s == "" {
		return 1
	}
	v, err := strconv.Atoi(strings.TrimSpace(s))
	if err != nil || v < 1 {
		return 1
	}
	return v
}

func visibleLen(s string) int { return len(s) }

func padTo(s string, w int) string {
	if len(s) >= w {
		return s
	}
	return s + strings.Repeat(" ", w-len(s))
}

func cellsOf(tr *dom.Node) []*dom.Node {
	var res []*dom.Node
	for _, ch := range tr.Children {
		if ch.Type == dom.NodeElement && (ch.Tag == "td" || ch.Tag == "th") {
			res = append(res, ch)
		}
	}
	return res
}

// headerChildren renders the header row cells padded/truncated to maxCol.
func (c *Converter) headerChildren(tr *dom.Node, maxCol int) []string {
	res := make([]string, maxCol)
	cells := cellsOf(tr)
	for i, cell := range cells {
		if i >= maxCol {
			break
		}
		m := c.cellMarkdown(cell, false)
		res[i] = m
	}
	return res
}

// cellMarkdown renders a cell (td/th).
func (c *Converter) cellMarkdown(cell *dom.Node, inline bool) string {
	sub := c.convChildren(cell.Children, c.newState(true))
	if len(sub) == 0 {
		return ""
	}
	return strings.Join(sub, "\n\n")
}

// tableFallback renders the table content as blocks.
func (c *Converter) tableFallback(n *dom.Node) []string {
	var res []string
	var walk func(*dom.Node)
	walk = func(t *dom.Node) {
		for _, ch := range t.Children {
			if ch.Type != dom.NodeElement {
				continue
			}
			switch ch.Tag {
			case "caption":
				res = append(res, c.convChildren(ch.Children, c.newState(true))...)
			case "colgroup", "col":
			case "tr":
				var sb strings.Builder
				for _, cell := range cellsOf(ch) {
					sb.WriteString(c.cellMarkdown(cell, true))
				}
				res = append(res, sb.String())
			case "thead", "tbody", "tfoot":
				walk(ch)
			default:
				walk(ch)
			}
		}
	}
	walk(n)
	return res
}
