				col++
			}
			for i := 0; i < cs; i++ {
				for j := 0; j < rs; j++ {
					rr := r + j
					cc := col + i
					if getOcc(rr)[cc] {
						continue
					}
					getOcc(rr)[cc] = true
					if j == 0 && i == 0 {
						grid[[2]int{rr, cc}] = ch
					} else {
						spans[[2]int{rr, cc}] = ch
					}
					if rr+1 > rowCount+rowSpanExtra {
						rowSpanExtra = rr + 1 - rowCount
					}
					if cc+1 > maxCol {
						maxCol = cc + 1
					}
