			}
		case "colgroup", "col":
		case "thead":
			collectRows(ch, d, true)
		case "tbody", "tfoot":
			collectRows(ch, d, false)
		case "tr":
			d.rows = append(d.rows, ch)
			if d.header == nil {
				if inHead {
					d.header = ch
				}
			}
		default:
			collectRows(ch, d, inHead)
		}
	}
}

func hasTh(tr *dom.Node) bool {
	for _, ch := range tr.Children {
		if ch.Type == dom.NodeElement && ch.Tag == "th" {
			return true
		}
	}
	return false
}

func cellsOf(tr *dom.Node) []*dom.Node {
	var res []*dom.Node
	for _, ch := range tr.Children {
		if ch.Type == dom.NodeElement && (ch.Tag == "td" || ch.Tag == "th") {
			res = append(res, ch)
		}
	}
	return res
}

func parseSpan(s string) int {
	if s == "" {
		return 1
	}
	v, err := strconv.Atoi(strings.TrimSpace(s))
	if err != nil || v < 1 {
		return 1
	}
	return v
}

func (c *Converter) convTable(n *dom.Node) []string {
