				for j := 0; j < rs; j++ {
					rr := r + j
					if rr >= totalRows {
						totalRows = rr + 1
					}
					mark(rr, col+i, cell, i == 0 && j == 0)
				}
			}
			col += cs
		}
	}
	// render cells
	headerCells := make([]string, maxCol)
	if d.header != nil {
		for cc := 0; cc < maxCol; cc++ {
			if cell := grid[[2]int{0, cc}]; cell != nil {
				headerCells[cc] = c.cellMarkdown(cell)
			}
		}
	}
	bodyCells := make([][]string, totalRows)
	for r := 0; r < totalRows; r++ {
		bodyCells[r] = make([]string, maxCol)
	}
