				} else {
					sb.WriteString("| " + cells[cc] + " ")
				}
			default:
				if isSep {
					sb.WriteString("|---")
				} else {
					sb.WriteString("|" + cells[cc])
				}
			}
		}
		sb.WriteString("|")
		return sb.String()
	}
