	for r := 0; r < totalRows; r++ {
		if c.opts.SkipEmptyRows {
			allEmpty := true
			for cc := 0; cc < maxCol; cc++ {
				if bodyCells[r][cc] != "" {
					allEmpty = false
					break
				}
			}
			if allEmpty {
				continue
			}
		}
		bodyLines = append(bodyLines, line(bodyCells[r], false))
	}
