// spanCell renders a cell that is covered by a colspan/rowspan of another cell.
func (c *Converter) spanCell(sp *dom.Node) string {
	if c.opts.SpanCellBehavior == "mirror" {
		return c.cellMarkdown(sp)
	}
	return ""
}

func (c *Converter) cellMarkdown(cell *dom.Node) string {
	sub := c.convChildren(cell.Children, c.newState(true))
	if len(sub) == 0 {
		return ""
	}
	return strings.Join(sub, blockSep)
}

// tableFallback renders the table content as plain blocks.
func (c *Converter) tableFallback(n *dom.Node) []string {
	var res []string
	var walk func(*dom.Node)
	walk = func(t *dom.Node) {
		for _, ch := range t.Children {
			if ch.Type != dom.NodeElement {
				continue
			}
			switch ch.Tag {
			case "caption":
				res = append(res, c.convChildren(ch.Children, c.newState(true))...)
			case "colgroup", "col":
			case "tr":
