package converter

import (
	"net/url"
	"strconv"
	"strings"

	"html2markdown/internal/dom"
)

// resolveURL resolves a relative URL against the configured domain.
func (c *Converter) resolveURL(raw string) string {
	if raw == "" {
		return ""
	}
	if c.domain == nil {
		return raw
	}
	u, err := url.Parse(raw)
	if err != nil {
		return raw
	}
	return c.domain.ResolveReference(u).String()
}

// ---------------------------------------------------------------------------
// code content (used by <pre> and inline code)
// ---------------------------------------------------------------------------

func (c *Converter) codeContent(n *dom.Node) string {
	s := c.codeContentChildren(n.Children)
	s = strings.TrimSuffix(s, "\n")
	return s
}

func (c *Converter) codeContentChildren(children []*dom.Node) string {
	var sb strings.Builder
	for _, n := range children {
		if n.Type == dom.NodeText {
			sb.WriteString(n.Text)
			continue
		}
		if n.Type != dom.NodeElement {
			continue
		}
		switch n.Tag {
		case "div":
			sb.WriteString("\n")
			sb.WriteString(c.codeContentChildren(n.Children))
		case "h1", "h2", "h3", "h4", "h5", "h6":
			sb.WriteString(c.codeContentChildren(n.Children))
			sb.WriteString("\n")
		case "blockquote":
			sb.WriteString(" \"")
			sb.WriteString(c.codeContentChildren(n.Children))
			sb.WriteString("\" ")
		case "br":
			sb.WriteString("\n")
		case "script", "style", "textarea", "template", "noscript", "title",
			"iframe", "noembed", "noframes", "plaintext":
		default:
			sb.WriteString(c.codeContentChildren(n.Children))
		}
	}
	return sb.String()
}

// ---------------------------------------------------------------------------
// table plugin
// ---------------------------------------------------------------------------

// tableData holds the parsed rows of a table.
type tableData struct {
	header  *dom.Node
	rows    []*dom.Node // tr elements in document order
	caption *dom.Node
}

// collectRows walks the table and collects rows/caption in document order.
func collectRows(t *dom.Node, d *tableData, inHead bool) {
	for _, ch := range t.Children {
		if ch.Type != dom.NodeElement {
			continue
		}
		switch ch.Tag {
		case "caption":
			if d.caption == nil {
				d.caption = ch
			}
		case "colgroup", "col":
		case "thead":
			collectRows(ch, d, true)
		case "tbody", "tfoot":
			collectRows(ch, d, false)
		case "tr":
			d.rows = append(d.rows, ch)
			if d.header == nil {
				if inHead {
					d.header = ch
				}
			}
		default:
			collectRows(ch, d, inHead)
		}
	}
}

func hasTh(tr *dom.Node) bool {
	for _, ch := range tr.Children {
		if ch.Type == dom.NodeElement && ch.Tag == "th" {
			return true
		}
	}
	return false
}

func cellsOf(tr *dom.Node) []*dom.Node {
	var res []*dom.Node
	for _, ch := range tr.Children {
		if ch.Type == dom.NodeElement && (ch.Tag == "td" || ch.Tag == "th") {
			res = append(res, ch)
		}
	}
	return res
}

func parseSpan(s string) int {
	if s == "" {
		return 1
	}
	v, err := strconv.Atoi(strings.TrimSpace(s))
	if err != nil || v < 1 {
		return 1
	}
	return v
}

func (c *Converter) convTable(n *dom.Node) []string {
	if strings.EqualFold(n.Get("role"), "presentation") && !c.opts.PresentationTables {
		return c.tableFallback(n)
	}
	d := &tableData{}
	collectRows(n, d, false)
	if d.header == nil && len(d.rows) > 0 && (c.opts.HeaderPromotion || hasTh(d.rows[0])) {
		d.header = d.rows[0]
	}
	rows := d.rows
	if len(rows) == 0 && d.caption == nil {
		return nil
	}
	if len(rows) == 0 {
		// only a caption
		if d.caption != nil {
			return c.convChildren(d.caption.Children, c.newState(true))
		}
		return nil
	}
	// grid: map (row,col) -> cell node ; map (row,col) -> spanning cell node
	grid := map[[2]int]*dom.Node{}
	spanCells := map[[2]int]*dom.Node{}
	maxCol := 1
	occ := map[int]map[int]bool{}
	mark := func(r, cc int, cell *dom.Node, primary bool) {
		if occ[r] == nil {
			occ[r] = map[int]bool{}
		}
		if occ[r][cc] {
			return
		}
		occ[r][cc] = true
		if primary {
			grid[[2]int{r, cc}] = cell
		} else {
			spanCells[[2]int{r, cc}] = cell
		}
		if cc+1 > maxCol {
			maxCol = cc + 1
		}
	}
	totalRows := len(rows)
	for r, tr := range rows {
		col := 0
		for _, cell := range cellsOf(tr) {
			cs := parseSpan(cell.Get("colspan"))
			rs := parseSpan(cell.Get("rowspan"))
			for occ[r] != nil && occ[r][col] {
				col++
			}
			for i := 0; i < cs; i++ {
				for j := 0; j < rs; j++ {
					rr := r + j
					if rr >= totalRows {
						totalRows = rr + 1
					}
					mark(rr, col+i, cell, i == 0 && j == 0)
				}
			}
			col += cs
		}
	}
	// render cells
	headerCells := make([]string, maxCol)
	if d.header != nil {
		for cc := 0; cc < maxCol; cc++ {
			if cell := grid[[2]int{0, cc}]; cell != nil {
				headerCells[cc] = c.cellMarkdown(cell)
			}
		}
	}
	bodyCells := make([][]string, totalRows)
	for r := 0; r < totalRows; r++ {
		bodyCells[r] = make([]string, maxCol)
	}
	fallback := false
	for cc := 0; cc < maxCol; cc++ {
		if strings.Contains(headerCells[cc], "\n") {
			fallback = true
		}
	}
	for r, tr := range rows {
		for cc := 0; cc < maxCol; cc++ {
			if sp := spanCells[[2]int{r, cc}]; sp != nil {
				bodyCells[r][cc] = c.spanCell(sp)
				continue
			}
			if cell := grid[[2]int{r, cc}]; cell != nil {
				m := c.cellMarkdown(cell)
				bodyCells[r][cc] = m
				if strings.Contains(m, "\n") {
					fallback = true
				}
			}
		}
	}
	if fallback {
		return c.tableFallback(n)
	}
	// widths
	widths := make([]int, maxCol)
	for cc := 0; cc < maxCol; cc++ {
		w := len(headerCells[cc])
		for r := 0; r < totalRows; r++ {
			if l := len(bodyCells[r][cc]); l > w {
				w = l
			}
		}
		widths[cc] = w
	}
	pad := c.opts.CellPadding
	var line func(cells []string, isSep bool) string
	line = func(cells []string, isSep bool) string {
		var sb strings.Builder
		for cc := 0; cc < maxCol; cc++ {
			switch pad {
			case "aligned":
				if isSep {
					sb.WriteString("|" + strings.Repeat("-", widths[cc]+2))
				} else {
					sb.WriteString("| " + padTo(cells[cc], widths[cc]) + " ")
				}
			case "minimal":
				if isSep {
					sb.WriteString("|---")
				} else {
					sb.WriteString("| " + cells[cc] + " ")
				}
			default:
				if isSep {
					sb.WriteString("|---")
				} else {
					sb.WriteString("|" + cells[cc])
				}
			}
		}
		sb.WriteString("|")
		return sb.String()
	}
	var bodyLines []string
	for r := 0; r < totalRows; r++ {
		if c.opts.SkipEmptyRows {
			allEmpty := true
			for cc := 0; cc < maxCol; cc++ {
				if bodyCells[r][cc] != "" {
					allEmpty = false
					break
				}
			}
			if allEmpty {
				continue
			}
		}
		bodyLines = append(bodyLines, line(bodyCells[r], false))
	}
	out := line(headerCells, false) + "\n" + line(nil, true) + "\n" + strings.Join(bodyLines, "\n")
	res := []string{out}
	if d.caption != nil {
		res = append(res, c.convChildren(d.caption.Children, c.newState(true))...)
	}
	return res
}

// spanCell renders a cell that is covered by a colspan/rowspan of another cell.
func (c *Converter) spanCell(sp *dom.Node) string {
	if c.opts.SpanCellBehavior == "mirror" {
		return c.cellMarkdown(sp)
	}
	return ""
}

func (c *Converter) cellMarkdown(cell *dom.Node) string {
	sub := c.convChildren(cell.Children, c.newState(true))
	if len(sub) == 0 {
		return ""
	}
	return strings.Join(sub, blockSep)
}

// tableFallback renders the table content as plain blocks.
func (c *Converter) tableFallback(n *dom.Node) []string {
	var res []string
	var walk func(*dom.Node)
	walk = func(t *dom.Node) {
		for _, ch := range t.Children {
			if ch.Type != dom.NodeElement {
				continue
			}
			switch ch.Tag {
			case "caption":
				res = append(res, c.convChildren(ch.Children, c.newState(true))...)
			case "colgroup", "col":
			case "tr":
				var sb strings.Builder
				for _, cell := range cellsOf(ch) {
					sb.WriteString(c.cellMarkdown(cell))
				}
				res = append(res, sb.String())
			default:
				walk(ch)
			}
		}
	}
	walk(n)
	return res
}

func padTo(s string, w int) string {
	if len(s) >= w {
		return s
	}
	return s + strings.Repeat(" ", w-len(s))
}
