// Package selector implements a small CSS selector engine with the same
// error messages as the reference implementation.
package selector

import (
	"fmt"
	"strings"
)

// SelectorError is returned for an invalid selector.
type SelectorError struct {
	Msg string
}

func (e *SelectorError) Error() string { return e.Msg }

type attrOp int

const (
	attrExists attrOp = iota
	attrEqual
	attrIncludes
	attrDashMatch
	attrPrefix
	attrSuffix
	attrSubstring
)

type attrSel struct {
	name  string
	op    attrOp
	value string
}

type pseudo struct {
	name    string
	arg     string   // for nth-child / lang / not / has
	expr    *nthExpr // for nth-*
	sel     *Sel     // for not / has
}

type compound struct {
	tag      string
	universal bool
	id       string
	classes  []string
	attrs    []attrSel
	pseudos  []pseudo
}

type nthExpr struct {
	a int
	b int
}

type complexSel struct {
	parts []*compound
	combs []string // combinator before parts[i] (i>0): " ", ">", "+", "~"
}

// Sel is a parsed selector (possibly a comma separated group).
type Sel struct {
	groups []*complexSel
	raw    string
}

// ---------------------------------------------------------------------------
// lexer
// ---------------------------------------------------------------------------

type lex struct {
	src string
	pos int
}

func (l *lex) eof() bool { return l.pos >= len(l.src) }

func (l *lex) peek() byte {
	if l.eof() {
		return 0
	}
	return l.src[l.pos]
}

func (l *lex) next() byte {
	c := l.peek()
	if c != 0 {
		l.pos++
	}
	return c
}

func isNameChar(c byte) bool {
	return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' ||
		c == '-' || c == '_' || c >= 0x80
}

func isSpace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f'
}

func (l *lex) skipWS() {
	for !l.eof() && isSpace(l.src[l.pos]) {
		l.pos++
	}
}

func (l *lex) ident() (string, error) {
	start := l.pos
	for !l.eof() && isNameChar(l.src[l.pos]) {
		l.pos++
	}
	if l.pos == start {
		return "", &SelectorError{Msg: "expected identifier, found " + found(l) + " instead"}
	}
	return l.src[start:l.pos], nil
}

func (l *lex) found() string {
	if l.eof() {
		return "EOF"
	}
	return fmt.Sprintf("%q", string(l.src[l.pos]))
}

// ---------------------------------------------------------------------------
// parser
// ---------------------------------------------------------------------------

func Parse(s string) (*Sel, error) {
	if s == "" {
		return nil, &SelectorError{Msg: "empty string"}
	}
	sel := &Sel{raw: s}
	l := &lex{src: s}
	var groups []*complexSel
	for {
		l.skipWS()
		if l.eof() {
			return nil, &SelectorError{Msg: "expected identifier, found EOF instead"}
		}
		cs, err := parseComplex(l)
		if err != nil {
			return nil, err
		}
		groups = append(groups, cs)
		l.skipWS()
		if l.eof() {
			break
		}
		if l.peek() == ',' {
			l.pos++
			continue
		}
		return nil, &SelectorError{Msg: fmt.Sprintf("parsing %q: %d bytes left over", s, len(s)-l.pos)}
	}
	sel.groups = groups
	return sel, nil
}

func parseComplex(l *lex) (*complexSel, error) {
	cs := &complexSel{}
	for {
		l.skipWS()
		comp, err := parseCompound(l)
		if err != nil {
			return nil, err
		}
		cs.parts = append(cs.parts, comp)
		// combinator?
		save := l.pos
		l.skipWS()
		if l.eof() {
			return cs, nil
		}
		c := l.peek()
		if c == '>' || c == '+' || c == '~' {
			l.pos++
			cs.combs = append(cs.combs, string(c))
			continue
		}
		if isNameChar(c) || c == '*' || c == '[' || c == '.' || c == '#' || c == ':' {
			cs.combs = append(cs.combs, " ")
			continue
		}
		if c == ',' {
			l.pos = save
			return cs, nil
		}
		return cs, nil
	}
}

func parseCompound(l *lex) (*compound, error) {
	cp := &compound{}
	// tag or universal
	if l.eof() {
		return nil, &SelectorError{Msg: "expected identifier, found EOF instead"}
	}
	c := l.peek()
	if c == '*' {
		l.pos++
		cp.universal = true
	} else if isNameStart(c) {
		tag, err := l.ident()
		if err != nil {
			return nil, err
		}
		cp.tag = strings.ToLower(tag)
	} else if c == '#' || c == '.' || c == '[' || c == ':' {
		// start with id/class/attr/pseudo
	} else {
		return nil, &SelectorError{Msg: "expected identifier, found " + l.found() + " instead"}
	}
	for {
		if l.eof() {
			break
		}
		switch l.peek() {
		case '#':
			l.pos++
			id, err := l.ident()
			if err != nil {
				return nil, err
			}
			cp.id = id
		case '.':
			l.pos++
			cl, err := l.ident()
			if err != nil {
				return nil, err
			}
			cp.classes = append(cp.classes, cl)
		case '[':
			a, err := parseAttr(l)
			if err != nil {
				return nil, err
			}
			cp.attrs = append(cp.attrs, a)
		case ':':
			l.pos++
			double := false
			if l.peek() == ':' {
				l.pos++
				double = true
			}
			name, err := l.ident()
			if err != nil {
				return nil, err
			}
			if double {
				return nil, &SelectorError{Msg: fmt.Sprintf("pseudo-element %s found, but pseudo-elements support is disabled", name)}
			}
			p := pseudo{name: strings.ToLower(name)}
			// optional argument
			if l.peek() == '(' {
				l.pos++
				switch strings.ToLower(name) {
				case "not", "has":
					l.skipWS()
					if l.eof() {
						return nil, &SelectorError{Msg: "expected selector, found EOF instead"}
					}
					sub, err := parseComplex(l)
					if err != nil {
						return nil, err
					}
					l.skipWS()
					if l.eof() || l.peek() != ')' {
						return nil, &SelectorError{Msg: "expected identifier, found " + l.found() + " instead"}
					}
					l.pos++
					subsel := &Sel{groups: []*complexSel{sub}, raw: ""}
					p.sel = subsel
				case "lang":
					arg, err := parseLangArg(l)
					if err != nil {
						return nil, err
					}
					p.arg = arg
				case "nth-child", "nth-last-child", "nth-of-type", "nth-last-of-type":
					e, err := parseNth(l)
					if err != nil {
						return nil, err
					}
					p.expr = e
				default:
					return nil, &SelectorError{Msg: fmt.Sprintf("unknown pseudoclass or pseudoelement :%s", strings.ToLower(name))}
				}
			} else {
				switch strings.ToLower(name) {
				case "first-child", "last-child", "only-child", "first-of-type",
					"last-of-type", "only-of-type", "root", "empty", "link",
					"visited", "target", "hover", "active", "focus", "enabled",
					"disabled", "checked":
				default:
					return nil, &SelectorError{Msg: fmt.Sprintf("unknown pseudoclass or pseudoelement :%s", strings.ToLower(name))}
				}
			}
			cp.pseudos = append(cp.pseudos, p)
		default:
			return cp, nil
		}
	}
	return cp, nil
}

func isNameStart(c byte) bool {
	return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c == '-' || c == '_' || c >= 0x80
}

func parseAttr(l *lex) (attrSel, error) {
	// we are just after '['
	inner := 1
	for !l.eof() {
		if l.src[l.pos] == '[' {
			inner++
		} else if l.src[l.pos] == ']' {
			inner--
			if inner == 0 {
				break
			}
		}
		l.pos++
	}
	if l.eof() || inner != 0 {
		return attrSel{}, &SelectorError{Msg: "unexpected EOF in attribute selector"}
	}
	body := l.src[l.pos-inner+1:]
	end := len(body) - 1
	l.pos++
	// parse body[0:end]
	p := &lex{src: body[0:end]}
	p.skipWS()
	name, err := p.ident()
	if err != nil {
		return attrSel{}, err
	}
	p.skipWS()
	if p.eof() {
		return attrSel{Name: strings.ToLower(name)}, nil
	}
	op := attrExists
	switch p.peek() {
	case '=':
		p.pos++
		op = attrEqual
	case '~':
		if p.pos+1 < len(p.src) && p.src[p.pos+1] == '=' {
			p.pos += 2
			op = attrIncludes
		} else {
			return attrSel{}, &SelectorError{Msg: "unexpected character in attribute selector"}
		}
	case '|':
		if p.pos+1 < len(p.src) && p.src[p.pos+1] == '=' {
			p.pos += 2
			op = attrDashMatch
		} else {
			return attrSel{}, &SelectorError{Msg: "unexpected character in attribute selector"}
		}
	case '^':
		if p.pos+1 < len(p.src) && p.src[p.pos+1] == '=' {
			p.pos += 2
			op = attrPrefix
		} else {
			return attrSel{}, &SelectorError{Msg: "unexpected character in attribute selector"}
		}
	case '$':
		if p.pos+1 < len(p.src) && p.src[p.pos+1] == '=' {
			p.pos += 2
			op = attrSuffix
		} else {
			return attrSel{}, &SelectorError{Msg: "unexpected character in attribute selector"}
		}
	case '*':
		if p.pos+1 < len(p.src) && p.src[p.pos+1] == '=' {
			p.pos += 2
			op = attrSubstring
		} else {
			return attrSel{}, &SelectorError{Msg: "unexpected character in attribute selector"}
		}
	default:
		return attrSel{}, &SelectorError{Msg: "unexpected character in attribute selector"}
	}
	p.skipWS()
	var value string
	if p.peek() == '"' || p.peek() == '\'' {
		q := p.next()
		start := p.pos
		for !p.eof() && p.src[p.pos] != q {
			p.pos++
		}
		if p.eof() {
			return attrSel{}, &SelectorError{Msg: "unexpected EOF in attribute selector"}
		}
		value = p.src[start:p.pos]
		p.pos++
	} else {
		v, err := p.ident()
		if err != nil {
			return attrSel{}, err
		}
		value = v
	}
	p.skipWS()
	if !p.eof() {
		return attrSel{}, &SelectorError{Msg: fmt.Sprintf("unexpected character in attribute selector")}
	}
	return attrSel{Name: strings.ToLower(name), op: op, value: value}, nil
}

func parseLangArg(l *lex) (string, error) {
	var sb strings.Builder
	for !l.eof() {
		c := l.peek()
		if c == ')' {
			l.pos++
			return sb.String(), nil
		}
		sb.WriteByte(c)
		l.pos++
	}
	return "", &SelectorError{Msg: "expected selector, found EOF instead"}
}

func parseNth(l *lex) (*nthExpr, error) {
	// parse an+b
	e := &nthExpr{}
	orig := l.pos
	// an+b form: [+-]?[0-9]*n?([+-][0-9]+)?
	p.skipWS()
	sign := 1
	if !l.eof() && (l.peek() == '+' || l.peek() == '-') {
		if l.peek() == '-' {
			sign = -1
		}
		l.pos++
	}
	// optional number
	start := l.pos
	for !l.eof() && l.src[l.pos] >= '0' && l.src[l.pos] <= '9' {
		l.pos++
	}
	numStr := l.src[start:l.pos]
	hasNum := numStr != ""
	// 'n' or 'odd' or 'even'
	word := ""
	start = l.pos
	for !l.eof() && isNameChar(l.src[l.pos]) {
		l.pos++
	}
	word = l.src[start:l.pos]
	if strings.EqualFold(word, "odd") {
		e.a, e.b = 2, 1
		l.skipWS()
		if !l.eof() && l.peek() == ')' {
			l.pos++
			return e, nil
		}
		return nil, &SelectorError{Msg: "unexpected character while attempting to parse expression of form an+b"}
	}
	if strings.EqualFold(word, "even") {
		e.a, e.b = 2, 0
		l.skipWS()
		if !l.eof() && l.peek() == ')' {
			l.pos++
			return e, nil
		}
		return nil, &SelectorError{Msg: "unexpected character while attempting to parse expression of form an+b"}
	}
	if word == "n" || word == "N" {
		e.a = sign * 1
		if hasNum {
			e.b = sign * atoi(numStr)
		}
		// optional +b
		p.skipWS()
		if !l.eof() && (l.peek() == '+' || l.peek() == '-') {
			s2 := 1
			if l.peek() == '-' {
				s2 = -1
			}
			l.pos++
			p.skipWS()
			st := l.pos
			for !l.eof() && l.src[l.pos] >= '0' && l.src[l.pos] <= '9' {
				l.pos++
			}
			if st == l.pos {
				return nil, &SelectorError{Msg: "expected integer, but didn't find it"}
			}
			e.b = s2 * atoi(l.src[st:l.pos])
		}
		l.skipWS()
		if !l.eof() && l.peek() == ')' {
			l.pos++
			return e, nil
		}
		if l.eof() {
			return nil, &SelectorError{Msg: "unexpected EOF while attempting to parse expression of form an+b"}
		}
		return nil, &SelectorError{Msg: "unexpected character while attempting to parse expression of form an+b"}
	}
	if word == "" {
		if hasNum {
			e.a, e.b = 0, sign*atoi(numStr)
			l.skipWS()
			if !l.eof() && l.peek() == ')' {
				l.pos++
				return e, nil
			}
			if l.eof() {
				return nil, &SelectorError{Msg: "unexpected EOF while attempting to parse expression of form an+b"}
			}
			return nil, &SelectorError{Msg: "unexpected character while attempting to parse expression of form an+b"}
		}
		l.pos = orig
		return nil, &SelectorError{Msg: "unexpected character while attempting to parse expression of form an+b"}
	}
	l.pos = orig
	return nil, &SelectorError{Msg: "unexpected character while attempting to parse expression of form an+b"}
}

func atoi(s string) int {
	n := 0
	for i := 0; i < len(s); i++ {
		n = n*10 + int(s[i]-'0')
	}
	return n
}

// ---------------------------------------------------------------------------
// matching
// ---------------------------------------------------------------------------

// node is the minimal interface needed for matching.
type Matcher interface {
	Tag() string
	Attr(name string) string
	HasAttr(name string) bool
	Parent() Matcher
	ChildCount() int
	Child(i int) Matcher
	IsRoot() bool
	Children() []Matcher
	Text() string
}

// Match reports whether the selector matches the node.
func (s *Sel) Match(n Matcher) bool {
	for _, cs := range s.groups {
		if matchComplex(cs, cs.parts[len(cs.parts)-1], len(cs.parts)-1, n) {
			return true
		}
	}
	return false
}

func matchComplex(cs *complexSel, cp *compound, idx int, n Matcher) bool {
	if !matchCompound(cp, n) {
		return false
	}
	if idx == 0 {
		return true
	}
	comb := cs.combs[idx-1]
	switch comb {
	case " ":
		// any ancestor
		for p := n.Parent(); p != nil; p = p.Parent() {
			if matchComplex(cs, cs.parts[idx-1], idx-1, p) {
				return true
			}
		}
		return false
	case ">":
		p := n.Parent()
		if p == nil {
			return false
		}
		return matchComplex(cs, cs.parts[idx-1], idx-1, p)
	case "+":
		p := n.Parent()
		if p == nil {
			return false
		}
		children := p.Children()
		for i, c := range children {
			if sameNode(c, n) {
				for j := i - 1; j >= 0; j-- {
					if isElement(children[j]) {
						return matchComplex(cs, cs.parts[idx-1], idx-1, children[j])
					}
				}
				return false
			}
		}
		return false
	case "~":
		p := n.Parent()
		if p == nil {
			return false
		}
		children := p.Children()
		for i, c := range children {
			if sameNode(c, n) {
				for j := i - 1; j >= 0; j-- {
					if isElement(children[j]) && matchComplex(cs, cs.parts[idx-1], idx-1, children[j]) {
						return true
					}
				}
				return false
			}
		}
		return false
	}
	return false
}

// sameNode is implemented by the caller via a comparable identity: we use
// pointer equality through the children slice.
var _ = sameNode

func isElement(m Matcher) bool { return m != nil && m.Tag() != "" }

func matchCompound(cp *compound, n Matcher) bool {
	if cp.universal {
	} else if cp.tag != "" {
		if !strings.EqualFold(n.Tag(), cp.tag) {
			return false
		}
	}
	if cp.id != "" && n.Attr("id") != cp.id {
		return false
	}
	if len(cp.classes) > 0 {
		classes := strings.Fields(n.Attr("class"))
		for _, cl := range cp.classes {
			found := false
			for _, c := range classes {
				if c == cl {
					found = true
					break
				}
			}
			if !found {
				return false
			}
		}
	}
	for _, a := range cp.attrs {
		if !matchAttr(a, n) {
			return false
		}
	}
	for _, p := range cp.pseudos {
		if !matchPseudo(p, n) {
			return false
		}
	}
	return true
}

func matchAttr(a attrSel, n Matcher) bool {
	val, has := n.Attr(a.name), n.HasAttr(a.name)
	switch a.op {
	case attrExists:
		return has
	case attrEqual:
		return has && val == a.value
	case attrIncludes:
		if !has {
			return false
		}
		for _, f := range strings.Fields(val) {
			if f == a.value {
				return true
			}
		}
		return false
	case attrDashMatch:
		if !has {
			return false
		}
		return val == a.value || strings.HasPrefix(val, a.value+"-")
	case attrPrefix:
		return has && strings.HasPrefix(val, a.value)
	case attrSuffix:
		return has && strings.HasSuffix(val, a.value)
	case attrSubstring:
		return has && strings.Contains(val, a.value)
	}
	return false
}

func matchPseudo(p pseudo, n Matcher) bool {
	switch p.name {
	case "first-child":
		return isNthChild(n, 1)
	case "last-child":
		return isNthLastChild(n, 1)
	case "only-child":
		return isNthChild(n, 1) && isNthLastChild(n, 1)
	case "first-of-type":
		return isNthOfType(n, 1)
	case "last-of-type":
		return isNthLastOfType(n, 1)
	case "only-of-type":
		return isNthOfType(n, 1) && isNthLastOfType(n, 1)
	case "root":
		p := n.Parent()
		return p != nil && p.Tag() == "#document" || (p != nil && p.Tag() == "html")
	case "empty":
		return false
	case "link":
		return strings.EqualFold(n.Tag(), "a") && n.Attr("href") != ""
	case "visited", "hover", "active", "focus", "checked", "disabled":
		return false
	case "enabled":
		switch strings.ToLower(n.Tag()) {
		case "a", "button", "optgroup", "option", "fieldset":
			return true
		}
		return false
	case "target":
		return false
	case "lang":
		return false
	case "not":
		return p.sel != nil && !p.sel.Match(n)
	case "has":
		return p.sel != nil && hasDescendant(p.sel, n)
	case "contains":
		return strings.Contains(strings.ToLower(n.Text()), strings.ToLower(p.arg))
	case "nth-child":
		return matchNth(p.expr, n, false, false)
	case "nth-last-child":
		return matchNth(p.expr, n, false, true)
	case "nth-of-type":
		return matchNth(p.expr, n, true, false)
	case "nth-last-of-type":
		return matchNth(p.expr, n, true, true)
	}
	return false
}

func hasDescendant(s *Sel, n Matcher) bool {
	for _, c := range n.Children() {
		if isElement(c) {
			if s.Match(c) {
				return true
			}
			if hasDescendant(s, c) {
				return true
			}
		}
	}
	return false
}

func matchNth(e *nthExpr, n Matcher, ofType, fromLast bool) bool {
	if e == nil {
		return false
	}
	siblings := siblingsOf(n, ofType, fromLast)
	pos := 0
	for i, s := range siblings {
		if sameNode(s, n) {
			pos = i + 1
			break
		}
	}
	if pos == 0 {
		return false
	}
	a, b := e.a, e.b
	if a == 0 {
		return b == pos
	}
	d := pos - b
	if a > 0 {
		return d >= 0 && d%a == 0
	}
	d = -d
	return d >= 0 && d%(-a) == 0
}

func siblingsOf(n Matcher, ofType, fromLast bool) []Matcher {
	p := n.Parent()
	if p == nil {
		return nil
	}
	var res []Matcher
	for _, c := range p.Children() {
		if !isElement(c) {
			continue
		}
		if ofType && !strings.EqualFold(c.Tag(), n.Tag()) {
			continue
		}
		res = append(res, c)
	}
	if fromLast {
		// reverse
		for i, j := 0, len(res)-1; i < j; i, j = i+1, j-1 {
			res[i], res[j] = res[j], res[i]
		}
	}
	return res
}

func isNthChild(n Matcher, idx int) bool {
	sib := siblingsOf(n, false, false)
	return len(sib) >= idx && sameNode(sib[idx-1], n)
}

func isNthLastChild(n Matcher, idx int) bool {
	sib := siblingsOf(n, false, true)
	return len(sib) >= idx && sameNode(sib[idx-1], n)
}

func isNthOfType(n Matcher, idx int) bool {
	sib := siblingsOf(n, true, false)
	return len(sib) >= idx && sameNode(sib[idx-1], n)
}

func isNthLastOfType(n Matcher, idx int) bool {
	sib := siblingsOf(n, true, true)
	return len(sib) >= idx && sameNode(sib[idx-1], n)
}
