func parseAttr(l *lex) (attrSel, error) {
	// we are just after '['
	inner := 1
	for !l.eof() {
		if l.src[l.pos] == '[' {
			inner++
		} else if l.src[l.pos] == ']' {
			inner--
			if inner == 0 {
				break
			}
		}
		l.pos++
	}
	if l.eof() || inner != 0 {
		return attrSel{}, &SelectorError{Msg: "unexpected EOF in attribute selector"}
	}
	body := l.src[l.pos-inner+1:]
	end := len(body) - 1
	l.pos++
