	p := &lex{src: body[0:end]}
	p.skipWS()
	name, err := p.ident()
	if err != nil {
		return attrSel{}, err
	}
	p.skipWS()
	if p.eof() {
		return attrSel{Name: strings.ToLower(name)}, nil
	}
	op := attrExists
	switch p.peek() {
	case '=':
		p.pos++
		op = attrEqual
	case '~':
		if p.pos+1 < len(p.src) && p.src[p.pos+1] == '=' {
			p.pos += 2
			op = attrIncludes
		} else {
			return attrSel{}, &SelectorError{Msg: "unexpected character in attribute selector"}
		}
	case '|':
		if p.pos+1 < len(p.src) && p.src[p.pos+1] == '=' {
			p.pos += 2
			op = attrDashMatch
		} else {
			return attrSel{}, &SelectorError{Msg: "unexpected character in attribute selector"}
		}
	case '^':
		if p.pos+1 < len(p.src) && p.src[p.pos+1] == '=' {
			p.pos += 2
			op = attrPrefix
		} else {
			return attrSel{}, &SelectorError{Msg: "unexpected character in attribute selector"}
		}
	case '$':
		if p.pos+1 < len(p.src) && p.src[p.pos+1] == '=' {
			p.pos += 2
			op = attrSuffix
		} else {
			return attrSel{}, &SelectorError{Msg: "unexpected character in attribute selector"}
		}
	case '*':
		if p.pos+1 < len(p.src) && p.src[p.pos+1] == '=' {
			p.pos += 2
			op = attrSubstring
		} else {
			return attrSel{}, &SelectorError{Msg: "unexpected character in attribute selector"}
		}
	default:
		return attrSel{}, &SelectorError{Msg: "unexpected character in attribute selector"}
	}
	p.skipWS()
	var value string
	if p.peek() == '"' || p.peek() == '\'' {
		q := p.next()
		start := p.pos
		for !p.eof() && p.src[p.pos] != q {
			p.pos++
		}
		if p.eof() {
			return attrSel{}, &SelectorError{Msg: "unexpected EOF in attribute selector"}
		}
		value = p.src[start:p.pos]
		p.pos++
	} else {
		v, err := p.ident()
		if err != nil {
			return attrSel{}, err
		}
		value = v
	}
	p.skipWS()
	if !p.eof() {
		return attrSel{}, &SelectorError{Msg: fmt.Sprintf("unexpected character in attribute selector")}
	}
	return attrSel{Name: strings.ToLower(name), op: op, value: value}, nil
}

func parseLangArg(l *lex) (string, error) {
	var sb strings.Builder
	for !l.eof() {
		c := l.peek()
		if c == ')' {
			l.pos++
			return sb.String(), nil
		}
		sb.WriteByte(c)
		l.pos++
	}
	return "", &SelectorError{Msg: "expected selector, found EOF instead"}
}

func parseNth(l *lex) (*nthExpr, error) {
