		e.a, e.b = 2, 1
		l.skipWS()
		if !l.eof() && l.peek() == ')' {
			l.pos++
			return e, nil
		}
		return nil, &SelectorError{Msg: "unexpected character while attempting to parse expression of form an+b"}
