// parseArgs parses the command line arguments.
func parseArgs(args []string) ([]string, error) {
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			i++
			break
		}
		if len(a) < 2 || a[0] != '-' {
			break
		}
		numMinuses := 1
		if a[1] == '-' {
			numMinuses = 2
			if len(a) == 2 {
				i++
				break
			}
		}
		name := a[numMinuses:]
		if len(name) == 0 || name[0] == '-' || name[0] == '=' {
			return nil, fmt.Errorf("bad flag syntax: %s", a)
		}
		// split on "="
		value := ""
		hasValue := false
		if idx := strings.IndexByte(name, '='); idx >= 0 {
			value = name[idx+1:]
			name = name[:idx]
			hasValue = true
		}
		f := findFlag(name)
		if f == nil {
			if name == "help" || name == "h" {
				fHelp = true
				f = nil
			}
			if f == nil {
				return nil, fmt.Errorf("unknown flag: %s", flagPrefix(name))
			}
		}
		i++
		if f.kind == fBool {
			if !hasValue {
				*f.boolVal = true
				f.set = true
				continue
			}
			if err := setFlag(f, value); err != nil {
				return nil, err
			}
			continue
		}
		if !hasValue {
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: -%s", f.name)
			}
			value = args[i]
			i++
		}
		if err := setFlag(f, value); err != nil {
			return nil, err
		}
	}
	return args[i:], nil
}

