func parseArgs(args []string) ([]string, error) {
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			i++
			break
		}
		if len(a) < 2 || a[0] != '-' {
			break
		}
		numMinuses := 1
		if a[1] == '-' {
			numMinuses = 2
			if len(a) == 2 {
				i++
				break
			}
		}
		name := a[numMinuses:]
		if len(name) == 0 || name[0] == '-' || name[0] == '=' {
			return nil, fmt.Errorf("bad flag syntax: %s", a)
		}
		// split on "="
		value := ""
		hasValue := false
		if idx := strings.IndexByte(name, '='); idx >= 0 {
			value = name[idx+1:]
			name = name[:idx]
			hasValue = true
		}
		f := findFlag(name)
		if f == nil {
			if name == "help" || name == "h" {
				fHelp = true
				f = nil
			}
			if f == nil {
				return nil, fmt.Errorf("unknown flag: %s", flagPrefix(name))
			}
		}
		i++
		if f.kind == fBool {
			if !hasValue {
				*f.boolVal = true
				f.set = true
				continue
			}
			if err := setFlag(f, value); err != nil {
				return nil, err
			}
			continue
		}
		if !hasValue {
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: -%s", f.name)
			}
			value = args[i]
			i++
		}
		if err := setFlag(f, value); err != nil {
			return nil, err
		}
	}
	return args[i:], nil
}

// ---------------------------------------------------------------------------
// main
// ---------------------------------------------------------------------------

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
	rest, err := parseArgs(args)
	if err != nil {
		return fail(err.Error(), "")
	}
	if fHelp {
		fmt.Print(helpText)
		return 0
	}
	if fVersion {
		fmt.Printf("html2markdown\\n\\nGitVersion:  %s\\nGitCommit:   none\\nBuildDate:   unknown\\n", version)
		return 0
	}
	if len(rest) > 0 {
		return fail("unknown arguments: "+strings.Join(rest, " "), cliHint)
	}

	// table options require the table plugin
	if fTable {
		if fPadding != "" {
			switch fPadding {
			case "aligned", "minimal", "none", "":
			default:
				return fail("error while initializing \\"table\\" plugin: unknown value \\""+fPadding+"\\" for cell padding behavior", "")
			}
		}
		if fNewline != "" {
			switch fNewline {
			case "skip", "preserve", "":
			default:
				return fail("error while initializing \\"table\\" plugin: unknown value \\""+fNewline+"\\" for newline behavior", "")
			}
		}
		if fSpan != "" {
			switch fSpan {
			case "empty", "mirror", "":
			default:
				return fail("error while initializing \\"table\\" plugin: unknown value \\""+fSpan+"\\" for span cell behavior", "")
			}
		}
	} else {
		if fPadding != "" {
			return fail("--opt-table-cell-padding-behavior requires --plugin-table to be enabled", "")
		}
		if fNewline != "" {
			return fail("--opt-table-newline-behavior requires --plugin-table to be enabled", "")
		}
		if fSpan != "" {
			return fail("--opt-table-span-cell-behavior requires --plugin-table to be enabled", "")
		}
		if fHeader {
			return fail("--opt-table-header-promotion requires --plugin-table to be enabled", "")
		}
		if fPresent {
			return fail("--opt-table-presentation-tables requires --plugin-table to be enabled", "")
		}
		if fSkipEmpty {
			return fail("--opt-table-skip-empty-rows requires --plugin-table to be enabled", "")
		}
	}

	// gather input
	var files []string
	if fInput != "" {
		if strings.ContainsAny(fInput, "*?[") {
			m, err := filepath.Glob(fInput)
			if err != nil || len(m) == 0 {
				return fail("no files found matching pattern \\""+fInput+"\\"", globHint)
			}
			for _, f := range m {
				st, err := os.Stat(f)
				if err != nil {
					continue
				}
				if st.IsDir() {
					continue
				}
				files = append(files, f)
			}
			if len(files) == 0 {
				return fail("no files found matching pattern \\""+fInput+"\\"", globHint)
			}
		} else {
			st, err := os.Stat(fInput)
			if err != nil {
				return fail("no files found matching pattern \\""+fInput+"\\"", globHint)
			}
			if st.IsDir() {
				return fail("input path \\""+fInput+"\\" is a directory, not a file", globHint)
			}
			files = []string{fInput}
		}
	} else {
		data, err := readAll(os.Stdin)
		if err != nil {
			return fail(err.Error(), "")
		}
		files = nil
		stdinData = data
	}

	multiple := len(files) > 1

	// prepare output
	var outFile string
	if fOutput != "" {
		if strings.HasSuffix(fOutput, "/") {
			if err := os.MkdirAll(strings.TrimRight(fOutput, "/"), 0o755); err != nil {
				return fail(err.Error(), "")
			}
		} else if multiple {
			return fail(fmt.Sprintf("when processing multiple input files, --output %q must end with %q to indicate a directory", filepath.Base(fOutput), filepath.Base(fOutput)+"/"), "")
		} else {
			if st, err := os.Stat(fOutput); err == nil && st.IsDir() {
				b := filepath.Base(fOutput)
				return fail(fmt.Sprintf("path %q exists and is a directory, did you mean %q?", b, b+"/"),
					"The --output must end with \\"/\\" to indicate a directory")
			}
		}
	} else if multiple {
		return fail("when processing multiple input files --output needs to be a directory", globHint)
	}

	// convert
	var results []string
	if len(files) > 0 {
		for _, f := range files {
			data, err := os.ReadFile(f)
			if err != nil {
				return fail(err.Error(), "")
			}
			md, err := convertHTML(string(data))
			if err != nil {
				return fail(err.Error(), "")
			}
			if fOutput != "" {
				var target string
				if strings.HasSuffix(fOutput, "/") {
					target = fOutput + strings.TrimSuffix(filepath.Base(f), filepath.Ext(f)) + ".md"
				} else {
					target = fOutput
				}
				if err := writeFile(target, md); err != nil {
					return fail(err.Error(), "")
				}
			} else {
				results = append(results, md)
			}
		}
	} else {
		md, err := convertHTML(stdinData)
		if err != nil {
			return fail(err.Error(), "")
		}
		results = append(results, md)
	}

	if fOutput == "" {
		for _, r := range results {
			fmt.Println(r)
		}
	}
	return 0
}

var stdinData string

func convertHTML(src string) (string, error) {
	// initialize the plugins in the same order as the reference implementation
	if fTable {
		switch fPadding {
		case "", "aligned", "minimal", "none":
		default:
			return "", fmt.Errorf("error while initializing \\"table\\" plugin: unknown value %q for cell padding behavior", fPadding)
		}
		switch fNewline {
		case "", "skip", "preserve":
		default:
			return "", fmt.Errorf("error while initializing \\"table\\" plugin: unknown value %q for newline behavior", fNewline)
		}
		switch fSpan {
		case "", "empty", "mirror":
		default:
			return "", fmt.Errorf("error while initializing \\"table\\" plugin: unknown value %q for span cell behavior", fSpan)
		}
	}
	if fStrong != "" && fStrong != "**" && fStrong != "__" {
		return "", fmt.Errorf("invalid value for --opt-strong-delimiter=%q must be exactly 2 characters of \\"**\\" or \\"__\\"", fStrong)
	}
	doc := dom.Parse(src)
	if fInclude != "" {
		sel, err := selector.Parse(fInclude)
		if err != nil {
			return "", err
		}
		doc = selectInclude(doc, sel)
	}
	if fExclude != "" {
		sel, err := selector.Parse(fExclude)
		if err != nil {
			return "", err
		}
		selectExclude(doc, sel)
	}
	var plugins []string
	if fStrike {
		plugins = append(plugins, "strikethrough")
	}
	if fTable {
		plugins = append(plugins, "table")
	}
	opts := converter.Options{
		StrongDelimiter:    fStrong,
		Domain:             fDomain,
		Plugins:            plugins,
		CellPadding:        fPadding,
		HeaderPromotion:    fHeader,
		NewlineBehavior:    fNewline,
		PresentationTables: fPresent,
		SkipEmptyRows:      fSkipEmpty,
		SpanCellBehavior:   fSpan,
	}
	c := converter.New(opts)
	return c.Convert(doc), nil
}

func writeFile(path, content string) error {
	if _, err := os.Stat(path); err == nil {
		if !fOverwrite {
			return fmt.Errorf("output path %q already exists. Use --output-overwrite to replace existing files", path)
		}
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	return os.WriteFile(path, []byte(content), 0o644)
}

func selectInclude(doc *dom.Node, sel *selector.Sel) *dom.Node {
	var matched []*dom.Node
	var walk func(*dom.Node)
	walk = func(n *dom.Node) {
		for _, ch := range n.Children {
			if ch.Type == dom.NodeElement && sel.Match(ch) {
				matched = append(matched, ch)
				continue
			}
			walk(ch)
		}
	}
	walk(doc)
	root := newNode("#document")
	for _, m := range matched {
		m.Parent = nil
		root.appendChild(m)
	}
	return root
}

func selectExclude(doc *dom.Node, sel *selector.Sel) {
	var walk func(*dom.Node)
	walk = func(n *dom.Node) {
		kept := (*n).Children[:0]
		for _, ch := range n.Children {
			if ch.Type == dom.NodeElement && sel.Match(ch) {
				continue
			}
			walk(ch)
			kept = append(kept, ch)
		}
		n.Children = kept
	}
	walk(doc)
}

func newNode(tag string) *dom.Node {
	n := &dom.Node{Type: dom.NodeDocument, Tag: tag}
	n.Attrs = map[string]string{}
	return n
}
